          "text": "لَقِّنُوا مَوْتَاكُمْ: لَا إِلَهَ إِلَّا اللَّهُ.",
          "latin": "Laqqinū mawtākum: lā ilāha illā-llāh.",
          "explanationEs": "El Profeta ﷺ dijo: «Inculcad a vuestros moribundos: “No hay divinidad digna de adoración salvo Allah”». Se le recuerda con suavidad, sin agobiarlo ni insistir; el Profeta ﷺ dijo también: «Quien tenga como últimas palabras “lā ilāha illā-llāh” entrará al Paraíso» (Abu Dawud).",
          "note": "رواه مسلم"
