          "subtitleEs": "Del Corán: firmeza al morir",
          "text": "﴿رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَتَوَفَّنَا مُسْلِمِينَ۝﴾",
          "latin": "Rabbanā afrigh ʿalaynā ṣabran wa-tawaffanā muslimīn.",
