          "text": "لَا إِلَهَ إِلَّا اللَّهُ، إِنَّ لِلْمَوْتِ سَكَرَاتٍ.",
          "latin": "Lā ilāha illā-llāh, inna lil-mawti sakarāt.",
          "explanationEs": "No hay divinidad digna de adoración salvo Allah. Ciertamente la muerte tiene agonías. Lo decía el Profeta ﷺ en su última enfermedad mientras se pasaba las manos mojadas por el rostro.",
