          "subtitleEs": "Al terminar el entierro",
          "text": "اسْتَغْفِرُوا لِأَخِيكُمْ، وَسَلُوا لَهُ بِالتَّثْبِيتِ، فَإِنَّهُ الْآنَ يُسْأَلُ.",
          "latin": "Istaghfirū li-akhīkum, wa-salū lahu bit-tathbīt, fa-innahu l-āna yusʾal.",
          "explanationEs": "Cuando el Profeta ﷺ terminaba de enterrar a un difunto, se detenía junto a su tumba y decía: «Pedid perdón para vuestro hermano y pedid para él firmeza, pues ahora está siendo interrogado». Ibn Baz y al-Albani lo consideran válido.",
          "note": "رواه أبو داود (3221) وصححه الألباني"
