          "explanationEs": "¡Oh Allah! Perdónalo. ¡Oh Allah! Hazlo firme. Es una fórmula que concreta lo que ordena el hadiz anterior; los sabios explican que se puede decir con estas u otras palabras parecidas. No es un texto transmitido literalmente.",
