        {
          "itemNumber": 368,
          "subtitleAr": "عِنْدَ زِيَارَةِ الْقُبُورِ",
          "subtitleEs": "Al visitar los cementerios",
          "text": "السَّلَامُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ. أَنْتُمْ لَنَا فَرَطٌ، وَنَحْنُ لَكُمْ تَبَعٌ. أَسْأَلُ اللَّهَ الْعَافِيَةَ لَنَا وَلَكُمْ.",
          "latin": "As-salāmu ʿalaykum ahla ad-diyāri mina al-muʾminīna wa-l-muslimīn, wa-innā in shāʾa Allāhu bikum lāḥiqūn. Antum lanā faraṭun wa-naḥnu lakum tabaʿun. Asʾalu Allāha al-ʿāfiyata lanā wa-lakum.",
          "explanationEs": "La paz sea con vosotros, habitantes de estas moradas, creyentes y musulmanes. Si Allah quiere, nos reuniremos con vosotros. Vosotros nos habéis precedido y nosotros os seguiremos. Pido a Allah bienestar para nosotros y para vosotros.",
          "note": "رواه مسلم",
          "audioUrls": [
            "https://github.com/Mundial-45/ZadAlQulub-Audio/raw/refs/heads/main/Dua/dua%20368.opus"
          ]
        }
