          "itemNumber": 369,
          "subtitleAr": "مِنَ الْقُرْآنِ: لِلسَّابِقِينَ بِالْإِيمَانِ",
          "subtitleEs": "Del Corán: por los creyentes que nos precedieron",
          "text": "﴿رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلًّا لِلَّذِينَ آمَنُوا رَبَّنَا إِنَّكَ رَءُوفٌ رَحِيمٌ۝﴾",
          "latin": "Rabbanā-ghfir lanā wa-li-ikhwāninā-lladhīna sabaqūnā bil-īmān, wa lā tajʿal fī qulūbinā ghillan lilladhīna āmanū, Rabbanā innaka Raʾūfun Raḥīm.",
          "explanationEs": "¡Señor nuestro! Perdónanos a nosotros y a nuestros hermanos que nos precedieron en la fe, y no pongas en nuestros corazones rencor hacia los creyentes. ¡Señor nuestro! Tú eres Compasivo, Misericordioso. (Al-Hashr: 10)",
