        "text": "اللَّهُمَّ اهْدِنَا فِيمَنْ هَدَيْتَ، وَعَافِنَا فِيمَنْ عَافَيْتَ، وَتَوَلَّنَا فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لَنَا فِيمَا أَعْطَيْتَ، وَقِنَا بِعِزَّتِكَ شَرَّ مَا قَضَيْتَ؛ فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ.\nتَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ.\nلَكَ الْحَمْدُ عَلَى مَا قَضَيْتَ، وَلَكَ الشُّكْرُ عَلَى مَا أَعْطَيْتَ.\nنَسْتَغْفِرُكَ اللَّهُمَّ مِنْ جَمِيعِ الذُّنُوبِ وَالْخَطَايَا، وَنَتُوبُ إِلَيْكَ.\nاللَّهُمَّ اقْسِمْ لَنَا مِنْ خَشْيَتِكَ مَا تَحُولُ بِهِ بَيْنَنَا وَبَيْنَ مَعْصِيَتِكَ، وَمِنْ طَاعَتِكَ مَا تُبَلِّغُنَا بِهِ جَنَّتَكَ، وَمِنَ الْيَقِينِ مَا تُهَوِّنُ بِهِ عَلَيْنَا مَصَائِبَ الدُّنْيَا.\nوَمَتِّعْنَا اللَّهُمَّ بِأَسْمَاعِنَا وَأَبْصَارِنَا وَقُوَّاتِنَا أَبَدًا مَا أَبْقَيْتَنَا، وَاجْعَلْهُ الْوَارِثَ مِنَّا، وَاجْعَلْ ثَأْرَنَا عَلَى مَنْ ظَلَمَنَا، وَانْصُرْنَا عَلَى مَنْ عَادَانَا.\nوَلَا تَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّنَا، وَلَا مَبْلَغَ عِلْمِنَا، وَلَا إِلَى النَّارِ مَصِيرَنَا.\nوَاجْعَلِ اللَّهُمَّ الْجَنَّةَ دَارَنَا وَقَرَارَنَا، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ اغْفِرْ لِوَالِدَيْنَا، اللَّهُمَّ اغْفِرْ لِوَالِدَيْنَا وَارْحَمْهُمَا كَمَا رَبَّيَانِي صِغَارًا، فَاجْعَلْهُمْ فِي أَعْلَى عِلِّيِّينَ مَعَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ وَحَسُنَ أُولَئِكَ رَفِيقًا.\nاللَّهُمَّ اغْفِرْ لِجَمِيعِ مَوْتَى الْمُسْلِمِينَ، الَّذِينَ شَهِدُوا لَكَ بِالْوَحْدَانِيَّةِ، وَلِنَبِيِّكَ بِالرِّسَالَةِ، وَمَاتُوا عَلَى ذَلِكَ.\nاللَّهُمَّ اغْفِرْ لَهُمْ وَارْحَمْهُمْ، وَعَافِهِمْ وَاعْفُ عَنْهُمْ، وَأَكْرِمْ نُزُلَهُمْ، وَوَسِّعْ مُدْخَلَهُمْ، وَاغْسِلْهُمْ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِمْ مِنَ الذُّنُوبِ وَالْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ اجْعَلِ الْقُرْآنَ الْعَظِيمَ رَبِيعَ قُلُوبِنَا، وَنُورَ صُدُورِنَا، وَجَلَاءَ أَحْزَانِنَا، وَذَهَابَ هُمُومِنَا وَغُمُومِنَا، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ اجْعَلِ الْقُرْآنَ الْكَرِيمِ لَنَا فِي الدُّنْيَا قَرِينًا، وَفِي الْقَبْرِ مُؤْنِسًا، وَعَلَى الصِّرَاطِ نُورًا، وَفِي الْقِيَامَةِ شَفِيعًا وَإِلَى الْجَنَّةِ رَفِيقًا، وَمِنَ النَّارِ سِتْرًا وَحِجَابًا، وَمِنَ النَّارِ سِتْرًا وَحِجَابًا، وَإِلَى الْخَيْرَاتِ كُلِّهَا دَلِيلًا وَإِمَامًا، بِفَضْلِكَ وَجُودِكَ يَا أَكْرَمَ الْأَكْرَمِينَ.\nاللَّهُمَّ إِنَّكَ عَفُوٌّ كَرِيمٌ حَلِيمٌ عَظِيمٌ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا.\nاللَّهُمَّ عَافِنَا وَاعْفُ عَنَّا، وَتَقَبَّلْ مِنَّا وَأَقْبِلْنَا، وَتُبْ عَلَيْنَا وَسَامِحْنَا بِفَضْلِكَ يَا أَرْحَمَ الرَّاحِمِينَ.\nاللَّهُمَّ مَتِّعْنَا بِالنَّظَرِ إِلَى وَجْهِكَ الْكَرِيمِ.\nاللَّهُمَّ اجْعَلْنَا مِنَ الَّذِينَ تَجْرِي مِنْ تَحْتِهِمُ الْأَنْهَارُ فِي جَنَّاتِ النَّعِيمِ؛ دَعْوَاهُمْ فِيهَا سُبْحَانَكَ اللَّهُمَّ، وَتَحِيَّتُهُمْ فِيهَا سَلَامٌ، وَآخِرُ دَعْوَاهُمْ أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ.\nاللَّهُمَّ لَكَ أَسْلَمْنَا، وَبِكَ آمَنَّا، وَعَلَيْكَ تَوَكَّلْنَا، وَإِلَيْكَ أَنَبْنَا، وَبِكَ خَاصَمْنَا.\nفَاغْفِرْ لَنَا مَا قَدَّمْنَا وَمَا أَخَّرْنَا، وَمَا أَسْرَرْنَا وَمَا أَعْلَنَّا، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنَّا؛ إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ، لَا إِلَهَ إِلَّا أَنْتَ خَلَقْتَنَا وَنَحْنُ عَبِيدُكَ فَاغْفِرْ لَنَا، يَا رَبَّنَا، إِلَهَنَا وَخَالِقَنَا اجْتَمَعْنَا فِي مَسْجِدِنَا هَذَا، وَمِنَّا الشَّبَابُ وَمِنَّا الْأَطْفَالُ وَمِنَّا الشُّيُوخُ وَمِنَّا النِّسَاءُ.\nدَعَوْنَاكَ دُعَاءً وَاحِدًا وَرَجَاءً وَاحِدًا وَسُؤَالًا وَاحِدًا.\nاللَّهُمَّ أَعْتِقْ رِقَابَنَا مِنَ النَّارِ، وَرِقَابَ آبَائِنَا وَأُمَّهَاتِنَا وَأَزْوَاجِنَا وَأَوْلَادِنَا مِنَ النَّارِ، وَأَوْلَادِنَا مِنَ النَّارِ، بِرَحْمَتِكَ يَا عَزِيزُ يَا غَفَّارُ.\nاللَّهُمَّ اشْفِ مَرْضَانَا، وَارْحَمْ مَوْتَانَا، وَفُكَّ أَسْرَانَا.\nكَمَا نَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى، كَمَا نَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nرَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً، وَفِي الْآخِرَةِ حَسَنَةً، وَقِنَا عَذَابَ النَّارِ.\nاللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ.\nاللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ.",
        "note": "الشيخ قادر الكردي",
