        "itemNumber": 293,
        "text": "اللَّهُمَّ اجْعَلْنَا نَخْشَاكَ كَأَنَّا نَرَاكَ، وَأَسْعِدْنَا بِتَقْوَاكَ، وَمَتِّعْنَا بِرُؤْيَاكَ، وَاجْمَعْنَا مَعَ نَبِيِّكَ وَمُصْطَفَاكَ.\nاللَّهُمَّ اجْعَلْنَا نَخْشَاكَ كَأَنَّا نَرَاكَ، وَأَسْعِدْنَا بِتَقْوَاكَ، وَمَتِّعْنَا بِرُؤْيَاكَ.\nاللَّهُمَّ اهْدِنَا فِيمَنْ هَدَيْتَ، وَعَافِنَا فِيمَنْ عَافَيْتَ، وَتَوَلَّنَا فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لَنَا فِيمَا أَعْطَيْتَ، وَقِنَا بِعِزَّتِكَ شَرَّ مَا قَضَيْتَ؛ فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ. تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ. لَكَ الْحَمْدُ عَلَى مَا قَضَيْتَ، وَلَكَ الشُّكْرُ عَلَى مَا أَعْطَيْتَ. نَسْتَغْفِرُكَ اللَّهُمَّ مِنْ جَمِيعِ الذُّنُوبِ وَالْخَطَايَا، وَنَتُوبُ إِلَيْكَ.\nرَبَّنَا ظَلَمْنَا أَنْفُسَنَا، وَإِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا، لَنَكُونَنَّ مِنَ الْخَاسِرِينَ.\nرَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ، وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلًّا لِلَّذِينَ آمَنُوا، رَبَّنَا إِنَّكَ رَؤُوفٌ رَحِيمٌ.\nرَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا، وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً، إِنَّكَ أَنْتَ الْوَهَّابُ.\nاللَّهُمَّ يَا عَفُوُّ، يَا غَفُورُ، ارْحَمْ أَمْوَاتَ الْمُسْلِمِينَ، وَاغْفِرْ لَهُمْ أَجْمَعِينَ، وَعَافِهِمْ وَاعْفُ عَنْهُمْ، وَأَكْرِمْ نُزُلَهُمْ، وَوَسِّعْ مُدْخَلَهُمْ، وَاغْسِلْهُمْ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِمْ مِنَ الذُّنُوبِ وَالْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ.\nاللَّهُمَّ أَحْسِنْ وُقُوفَنَا بَيْنَ يَدَيْكَ، وَلَا تُخْزِنَا يَوْمَ الْعَرْضِ عَلَيْكَ. اللَّهُمَّ تَقَبَّلْ صَلَاتَنَا وَصِيَامَنَا وَقِيَامَنَا وَرُكُوعَنَا وَسُجُودَنَا.\nاللَّهُمَّ اجْعَلْنَا مِنْ عُتَقَائِكَ مِنَ النَّارِ. اللَّهُمَّ أَجِرْنَا مِنَ النَّارِ، وَأَجِرْنَا مِنْ خِزْيِ النَّارِ، وَأَجِرْنَا مِنْ كُلِّ عَمَلٍ يُقَرِّبُنَا إِلَى النَّارِ. اللَّهُمَّ أَدْخِلْنَا الْجَنَّةَ مَعَ الْأَبْرَارِ، بِرَحْمَتِكَ يَا عَزِيزُ يَا غَفَّارُ.\nاللَّهُمَّ اجْعَلْنَا يَا مَوْلَانَا فِي شَهْرِنَا هَذَا، وَفِي يَوْمِنَا هَذَا، وَفِي لَيْلَتِنَا هَذِهِ، مِنْ عُتَقَائِكَ مِنَ النَّارِ، وَاجْعَلْنَا مِنَ الْمَقْبُولِينَ الْفَائِزِينَ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنَ الْمَوْتِ وَكَرْبَتِهِ، وَالْقَبْرِ وَغُمَّتِهِ، وَالصِّرَاطِ وَزَلَّتِهِ، وَيَوْمِ الْقِيَامَةِ وَرَوْعَتِهِ.\nاللَّهُمَّ اجْعَلْنَا نَخْشَاكَ كَأَنَّا نَرَاكَ، وَأَسْعِدْنَا بِتَقْوَاكَ، وَمَتِّعْنَا بِرُؤْيَاكَ، وَاجْمَعْنَا مَعَ نَبِيِّكَ وَمُصْطَفَاكَ، بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِينَ.\nاللَّهُمَّ انْصُرِ الْإِسْلَامَ وَأَعِزَّ الْمُسْلِمِينَ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ. اللَّهُمَّ مَتِّعْنَا بِالنَّظَرِ إِلَى وَجْهِكَ الْكَرِيمِ، اللَّهُمَّ مَتِّعْنَا بِالنَّظَرِ إِلَى وَجْهِكَ الْكَرِيمِ، بِرَحْمَتِكَ يَا أَكْرَمَ الْأَكْرَمِينَ.\nاللَّهُمَّ لَكَ أَسْلَمْنَا، وَبِكَ آمَنَّا، وَعَلَيْكَ تَوَكَّلْنَا، وَإِلَيْكَ أَنَبْنَا، وَبِكَ خَاصَمْنَا، فَاغْفِرْ لَنَا مَا قَدَّمْنَا وَمَا أَخَّرْنَا، وَمَا أَسْرَرْنَا وَمَا أَعْلَنَّا، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنَّا. أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ، لَا إِلَهَ إِلَّا أَنْتَ.\nاللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ، بِرَحْمَتِكَ يَا أَكْرَمَ الْأَكْرَمِينَ.\nاللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ. اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ.",
