        "text": "اللَّهُمَّ اهْدِنَا فِيمَنْ هَدَيْتَ، وَعَافِنَا فِيمَنْ عَافَيْتَ، وَتَوَلَّنَا فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لَنَا فِيمَا أَعْطَيْتَ، وَقِنَا بِعِزَّتِكَ شَرَّ مَا قَضَيْتَ.\nنَسْتَغْفِرُكَ وَنَتُوبُ إِلَيْكَ.\nاللَّهُمَّ اقْسِمْ لَنَا مِنْ خَشْيَتِكَ مَا تَحُولُ بِهِ بَيْنَنَا وَبَيْنَ مَعْصِيَتِكَ، وَمِنْ طَاعَتِكَ مَا تُبَلِّغُنَا بِهِ جَنَّتَكَ، وَمِنَ الْيَقِينِ مَا تُهَوِّنُ بِهِ عَلَيْنَا مَصَائِبَ الدُّنْيَا.\nوَمَتِّعْنَا اللَّهُمَّ بِأَسْمَاعِنَا وَأَبْصَارِنَا وَقُوَّاتِنَا أَبَدًا مَا أَبْقَيْتَنَا، وَاجْعَلْهُ الْوَارِثَ مِنَّا، وَاجْعَلْ ثَأْرَنَا عَلَى مَنْ ظَلَمَنَا، وَانْصُرْنَا عَلَى مَنْ عَادَانَا.\nوَلَا تَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّنَا، وَلَا مَبْلَغَ عِلْمِنَا، وَلَا إِلَى النَّارِ مَصِيرَنَا.\nوَاجْعَلِ اللَّهُمَّ الْجَنَّةَ دَارَنَا وَقَرَارَنَا، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ رُدَّ الْمُسْلِمِينَ إِلَى دِينِكَ رَدًّا جَمِيلًا.\nاللَّهُمَّ انْصُرْنَا عَلَى أَنْفُسِنَا.\nاللَّهُمَّ اسْتَجِبْ دُعَاءَنَا وَاشْفِ مَرْضَانَا، وَارْحَمْ مَوْتَانَا، وَأَهْلِكْ أَعْدَاءَنَا وَلَا تُخَيِّبْ رَجَاءَنَا، وَاخْتِمْ بِالْبَاقِيَاتِ الصَّالِحَاتِ أَعْمَالَنَا.\nاللَّهُمَّ بَلَّغْنَا مِمَّا يُرْضِيكَ آمَالُنَا اللَّهُمَّ وَلِّ أُمُورَنَا خِيَارَنَا وَلَا تُوَلِّ أُمُورَنَا شِرَارَنَا.\nاللَّهُمَّ أَصْلِحْ أَحْوَالَنَا وَأَلِّفْ بَيْنَ قُلُوبِنَا، وَاخْتِمْ بِالْبَاقِيَاتِ الصَّالِحَاتِ أَعْمَالَنَا، اللَّهُمَّ أَصْلِحْ أَحْوَالَنَا وَأَلِّفْ بَيْنَ قُلُوبِنَا، وَاخْتِمْ بِالْبَاقِيَاتِ الصَّالِحَاتِ أَعْمَالَنَا وَبِرَحْمَتِكَ الْوَاسِعَةِ عُمَّنَا وَاكْفِنَا شَرَّ مَا أَهَمَّنَا وَغَمَّنَا بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ اشْفِ مَرْضَانَا، وَارْحَمْ مَوْتَانَا، وَفُكَّ أَسْرَانَا.\nكَمَا نَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى.\nاللَّهُمَّ اغْفِرْ لَنَا مَا قَدَّمْنَا وَمَا أَخَّرْنَا، وَمَا أَسْرَرْنَا وَمَا أَعْلَنَّا، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنَّا؛ إِنَّكَ أَنْتَ السَّمِيعُ الْقَرِيبُ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا، اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا، اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا، فَاعْفُ عَنَّا يَا كَرِيمُ، فَاعْفُ عَنَّا يَا رَحِيمُ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ اجْعَلْنَا مِنْ عُتَقَائِكَ مِنَ النَّارِ، اللَّهُمَّ اجْعَلْنَا مِنْ عُتَقَائِكَ مِنَ النَّارِ.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ خَيْرَ الْمَسْأَلَةِ، وَخَيْرَ الدُّعَاءِ، وَخَيْرَ النَّجَاحِ، وَخَيْرَ الْعِلْمِ، وَخَيْرَ الْعَمَلِ، وَخَيْرَ الثَّوَابِ، وَخَيْرَ الْحَيَاةِ وَثَبِّتْنَا، وَثَقِّلْ مَوَازِينَنَا، وَحَقِّقْ إِيمَانَنَا، وَارْفَعْ دَرَجَتَنَا، وَتَقَبَّلْ صِيَامَنَا وَقِيَامَنَا وَسُجُودَنَا وَرُكُوعَنَا، وَاغْفِرْ خَطِيئَاتِنَا، وَنَسْأَلُكَ الْعُلَا مِنَ الْجَنَّةِ.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ، وَعَزَائِمَ مَغْفِرَتِكَ، وَالسَّلَامَةَ مِنْ كُلِّ إِثْمٍ، وَالْغَنِيمَةَ مِنْ كُلِّ بِرٍّ، وَالْفَوْزَ بِالْجَنَّةِ، وَالنَّجَاةَ مِنَ النَّارِ.\nاللَّهُمَّ أَجِرْنَا مِنَ النَّارِ وَمِنْ خِزْيِ النَّارِ.\nاللَّهُمَّ أَدْخِلْنَا الْجَنَّةَ مَعَ الْأَبْرَارِ، اللَّهُمَّ أَدْخِلْنَا الْجَنَّةَ مَعَ الْأَبْرَارِ، بِرَحْمَتِكَ يَا عَزِيزُ يَا غَفَّارُ.\nرَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً، وَفِي الْآخِرَةِ حَسَنَةً، وَقِنَا عَذَابَ النَّارِ، وَقِنَا عَذَابَ النَّارِ.\nاللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ.\nاللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ.",
