        "text": "اللَّهُمَّ اهْدِنَا فِيمَنْ هَدَيْتَ، وَعَافِنَا فِيمَنْ عَافَيْتَ، وَتَوَلَّنَا فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لَنَا فِيمَا أَعْطَيْتَ، وَقِنَا بِعِزَّتِكَ شَرَّ مَا قَضَيْتَ؛ فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ.\nتَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ.\nلَكَ الْحَمْدُ عَلَى مَا قَضَيْتَ، وَلَكَ الشُّكْرُ عَلَى مَا أَعْطَيْتَ.\nنَسْتَغْفِرُكَ اللَّهُمَّ مِنْ جَمِيعِ الذُّنُوبِ وَالْخَطَايَا، وَنَتُوبُ إِلَيْكَ.\nاللَّهُمَّ أَصْلِحْ أَحْوَالَنَا، اللَّهُمَّ أَصْلِحْ أَحْوَالَنَا.\nاللَّهُمَّ أَظِلَّنَا تَحْتَ عَرْشِكَ يَوْمَ لَا ظِلَّ إِلَّا ظِلُّكَ.\nاللَّهُمَّ أَصْلِحْ لَنَا دِينَنَا الَّذِي هُوَ عِصْمَةُ أَمْرِنَا، وَأَصْلِحْ لَنَا دُنْيَانَا الَّتِي فِيهَا مَعَاشُنَا، وَأَصْلِحْ لَنَا آخِرَتَنَا الَّتِي إِلَيْهَا مَعَادُنَا، وَاجْعَلِ الْحَيَاةَ زِيَادَةً لَنَا فِي كُلِّ خَيْرٍ، وَاجْعَلِ الْمَوْتَ رَاحَةً لَنَا مِنْ كُلِّ شَرٍّ يَا أَمَانَ الْخَائِفِينَ وَيَا رَجَاءَ الْمُذْنِبِينَ يَا اللَّهُ، يَا رَحْمَنُ.\nاللَّهُمَّ ارْحَمْنَا يَوْمَ تُبَدَّلُ الْأَرْضُ غَيْرَ الْأَرْضِ وَالسَّمَاوَاتُ.\nاللَّهُمَّ ارْحَمْنَا إِذَا جَاءَ مُنْكَرٌ وَنَكِيرٌ وَأُلْقِيَ عَلَيْنَا السُّؤَالُ.\nاللَّهُمَّ أَلْهِمْنَا الْجَوَابَ اللَّهُمَّ ثَبِّتْنَا بِالْقَوْلِ الثَّابِتِ فِي الْحَيَاةِ الدُّنْيَا وَفِي الْآخِرَةِ بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ ارْحَمْنَا يَوْمَ يَفِرُّ الْمَرْءُ مِنْ أَخِيهِ وَأُمِّهِ وَأَبِيهِ وَصَاحِبَتِهِ وَبَنِيهِ لِكُلِّ امْرِئٍ مِنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ.\nاللَّهُمَّ ارْحَمْنَا يَوْمَ تَقُولُ لِجَهَنَّمَ هَلِ امْتَلَأْتِ وَتَقُولُ هَلِ مِنْ مَزِيدٍ، وَتَقُولُ هَلِ مِنْ مَزِيدٍ.\nاللَّهُمَّ اغْفِرْ لِلْمُسْلِمِينَ وَالْمُسْلِمَاتِ اللَّهُمَّ اغْفِرْ لِجَمِيعِ مَوْتَى الْمُسْلِمِينَ، الَّذِينَ شَهِدُوا لَكَ بِالْوَحْدَانِيَّةِ، وَلِنَبِيِّكَ بِالرِّسَالَةِ، وَمَاتُوا عَلَى ذَلِكَ.\nاللَّهُمَّ ارْحَمْهُمْ وَعَافِهِمْ وَاعْفُ عَنْهُمْ، وَأَكْرِمْ نُزُلَهُمْ، وَوَسِّعْ مُدْخَلَهُمْ، وَاغْسِلْهُمْ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِمْ مِنَ الذُّنُوبِ وَالْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ.\nاللَّهُمَّ أَنْزِلْ عَلَى قُبُورِهِمْ الضِّيَاءَ وَالنُّورَ وَالْفُسْحَةَ وَالسُّرُورَ، وَجَازِهِمْ بِالْإِحْسَانِ إِحْسَانًا وَبِالسَّيِّئَاتِ عَفْوًا وَغُفْرَانًا، اللَّهُمَّ أَنْزِلْ عَلَى قُبُورِهِمْ الضِّيَاءَ وَالنُّورَ وَالْفُسْحَةَ وَالسُّرُورَ، وَجَازِهِمْ بِالْإِحْسَانِ إِحْسَانًا وَبِالسَّيِّئَاتِ عَفْوًا وَغُفْرَانًا، أَنْزِلْ عَلَى قُبُورِهِمْ الضِّيَاءَ وَالنُّورَ وَالْفُسْحَةَ وَالسُّرُورَ، وَجَازِهِمْ بِالْإِحْسَانِ إِحْسَانًا وَبِالسَّيِّئَاتِ عَفْوًا وَغُفْرَانًا.\nاللَّهُمَّ انْقُلْهُمْ مِنْ ضِيقِ اللُّحُودِ بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِينَ.\nاللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا.\nاللَّهُمَّ عَافِنَا وَاعْفُ عَنَّا، وَتَقَبَّلْ مِنَّا وَأَقْبِلْنَا، وَتُبْ عَلَيْنَا وَسَامِحْنَا بِفَضْلِكَ يَا أَرْحَمَ الرَّاحِمِينَ.\nيَا أَكْرَمَ الْأَكْرَمِينَ.\nاللَّهُمَّ اشْفِ مَرْضَانَا، وَارْحَمْ مَوْتَانَا، وَفُكَّ أَسْرَانَا.\nكَمَا نَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى.\nاللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ.",
