        "itemNumber": 321,
        "text": "اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ مِلْءَ السَّمَاوَاتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا بَيْنَهُمَا وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ، أَهْلَ الثَّنَاءِ وَالْمَجْدِ، أَحَقُّ مَا قَالَ الْعَبْدُ وَكُلُّنَا لَكَ عَبْدٌ.\nاللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ لَكَ الْحَمْدُ كُلُّهُ وَبِيَدِكَ الْخَيْرُ كُلُّهُ وَإِلَيْكَ يُرْجَعُ الْأَمْرُ كُلُّهُ عَلَانِيَتُهُ وَسِرُّهُ نَحْمَدُكَ بِمَحَامِدِكَ كُلِّهَا مَا عَلِمْنَا مِنْهَا وَمَا لَمْ نَعْلَمْ سُبْحَانَكَ مَا عَبَدْنَاكَ حَقَّ عِبَادَتِكَ وَلَا قَدَرْنَاكَ حَقَّ قَدْرِكَ وَلَا شَكَرْنَاكَ حَقَّ شُكْرِكَ لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنَّا كُنَّا مِنَ الظَّالِمِينَ وَإِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا، لَنَكُونَنَّ مِنَ الْخَاسِرِينَ.\nرَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قِبَلِنَا رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ وَاعْفُ عَنَّا، وَاغْفِرْ لَنَا وَارْحَمْنَا أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ.\nرَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا، وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً، إِنَّكَ أَنْتَ الْوَهَّابُ.\nرَبَّنَا إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِي لِلْإِيمَانِ أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا.\nرَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا، وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الْأَبْرَارِ.\nرَبَّنَا وَآتِنَا مَا وَعَدْتَنَا عَلَى رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ الْقِيَامَةِ إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ.\nرَبَّنَا اجْعَلْنَا مُقِيمِي الصَّلَاةِ وَمِنْ ذُرِّيَّتِنَا رَبَّنَا، وَتَقَبَّلْ دُعَاءِ.\nرَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ.\nرَبَّنَا لَا تَجْعَلِ فِي قُلُوبِنَا غِلًّا لِلَّذِينَ آمَنُوا، رَبَّنَا إِنَّكَ رَؤُوفٌ رَحِيمٌ.\nرَبَّنَا وَآتِنَا مِنْ لَدُنْكَ رَحْمَةً، إِنَّكَ أَنْتَ الْوَهَّابُ.\nرَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِينَ.\nاللَّهُمَّ فَرِّجْ هُمُومَنَا وَنَفِّسْ كُرُوبَنَا وَاقْضِ دُيُونَنَا وَاشْفِ مَرْضَانَا، وَارْحَمْ مَوْتَانَا وَمَوْتَى الْمُسْلِمِينَ.\nاللَّهُمَّ خُصَّ مِنْهُمُ الْآبَاءَ وَالْأُمَّهَاتِ وَاجْعَلْ قُبُورَهُمْ رِيَاضًا مِنْ رِيَاضِ الْجِنَانِ وَلَا تَجْعَلْ قُبُورَهُمْ حُفَرًا مِنْ حُفَرِ النِّيرَانِ.\nاللَّهُمَّ أَعِزَّ الْإِسْلَامَ وَالْمُسْلِمِينَ وَأَذِلَّ الشِّرْكَ وَالْمُشْرِكِينَ وَاحْمِ حَوْزَةَ الدِّينِ وَاجْعَلْ هَذَا الْبَلَدَ آمِنًا مُطْمَئِنًّا رَخَاءً، وَسَائِرَ بِلَادِ الْمُسْلِمِينَ.\nاللَّهُمَّ احْفَظْ عَلَى هَذِهِ الْبِلَادِ عَقِيدَتَهَا وَأَمْنَهَا وَرَخَاءَهَا وَاسْتِقْرَارِهَا وَعُلَمَاءَهَا وَوُلَاةَ أَمْرِهَا وَمُقَدَّرَاتِهَا وَثَرَوَاتِهَا.\nاللَّهُمَّ وَفِّقْ إِمَامَنَا بِتَوْفِيقِكَ وَأَيِّدْهُ بِتَأْيِيدِكَ وَوَفِّقْهُ وَوَلِيَّ عَهْدِهِ، وَأَعْوَانَهُمْ لِكُلِّ مَا فِيهِ صَلَاحٌ لِلْبِلَادِ وَالْعِبَادِ وَلِكُلِّ مَا فِيهِ عِزٌّ وَنَصْرٌ وَتَمْكِينٌ لِلْإِسْلَامِ وَالْمُسْلِمِينَ.\nاللَّهُمَّ احْفَظْ رِجَالَ أَمْنِنَا وَجُنُودَنَا عَلَى ثُغُورِنَا بِحِفْظِكَ، وَاكْلَأْهُمْ بِرِعَايَتِكَ.\nاللَّهُمَّ مَنْ أَرَادَنَا وَأَرَادَ بِلَادَنَا وَبِلَادَ الْمُسْلِمِينَ بِسُوءٍ أَوْ فِتْنَةٍ فَأَشْغِلْهُ فِي نَفْسِهِ وَاجْعَلِ كَيْدَهُ تَدْمِيرًا عَلَيْهِ يَا قَوِيُّ يَا عَزِيزُ.\nاللَّهُمَّ عَلَيْكَ بِأَعْدَاءِ الْإِسْلَامِ وَالْمُسْلِمِينَ.\nاللَّهُمَّ اضْرِبِ الظَّالِمِينَ بِالظَّالِمِينَ، وَأَخْرِجِ الْمُسْلِمِينَ مِنْ بَيْنِهِمْ سَالِمِينَ.\nاللَّهُمَّ اقْتُلْهُمْ بَدَدًا وَأَحْصِهِمْ عَدَدًا اللَّهُمَّ إِنَّا نَسْأَلُكَ أَنْ تُرِيَنَا فِيهِمْ عَجَائِبَ قُدْرَتِكَ يَا قَوِيُّ يَا عَزِيزُ يَا ذَا الْعَرْشِ الْمَجِيدِ يَا فَعَّالُ لِمَا يُرِيدُ.\nاللَّهُمَّ تَقَبَّلْ مِنَّا؛ إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ، وَاغْفِرْ لَنَا إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ، وَتُبْ عَلَيْنَا، إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ سُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَ وَسَلَامٌ عَلَى الْمُرْسَلِينَ، وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ.\nوَصَلِّ اللَّهُمَّ وَسَلِّمْ وَبَارِكْ عَلَى نَبِيِّنَا مُحَمَّدٍ وَعَلَى آلِهِ وَصَحْبِهِ أَجْمَعِينَ.",
        "note": "الشيخ ياسر الدوسري",
