        "text": "اللَّهُمَّ اهْدِنَا فِيمَنْ هَدَيْتَ، وَعَافِنَا فِيمَنْ عَافَيْتَ، وَتَوَلَّنَا فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لَنَا فِيمَا أَعْطَيْتَ، وَقِنَا بِرَحْمَتِكَ، وَاصْرِفْ عَنَّا شَرَّ مَا قَضَيْتَ، فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ.\nتَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ.\nاللَّهُمَّ آتِ نُفُوسَنَا تَقْوَاهَا، وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا، أَنْتَ وَلِيُّهَا وَمَوْلَاهَا.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهِ، عَاجِلِهِ وَآجِلِهِ، مَا عَلِمْنَا مِنْهُ وَمَا لَمْ نَعْلَمْ، وَنَعُوذُ بِكَ مِنَ الشَّرِّ كُلِّهِ، عَاجِلِهِ وَآجِلِهِ، مَا عَلِمْنَا مِنْهُ وَمَا لَمْ نَعْلَمْ.\nاللَّهُمَّ اغْفِرْ لِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَالْمُسْلِمِينَ وَالْمُسْلِمَاتِ، الْأَحْيَاءِ مِنْهُمْ وَالْأَمْوَاتِ.\nاللَّهُمَّ فَرِّجْ هُمُومَنَا وَنَفِّسْ كُرُوبَنَا وَاقْضِ دُيُونَنَا وَاشْفِ مَرْضَانَا وَعَافِ مُبْتَلَانَا وَعَافِ مُبْتَلَانَا، وَتَقَبَّلْ صِيَامَنَا وَقِيَامَنَا وَلَا تَدَعْ لَنَا حَاجَةً مِنْ حَوَائِجِ الدُّنْيَا هِيَ لَكَ رِضًا وَلَنَا فِيهَا صَلَاحٌ إِلَّا أَعَنْتَنَا عَلَى قَضَائِهَا.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ يَا إِلَهَ الْأَوَّلِينَ وَالْآخِرِينَ يَا مَنْ لَا يُعْجِزُهُ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ يَا مَنْ، إِذَا أَرَادَ شَيْئًا فَإِنَّمَا يَقُولُ لَهُ كُنْ فَيَكُونُ يَا مَنْ هُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ يَا مَنْ هُوَ أَكْبَرُ مِمَّا نَخَافُ وَنَحْذَرُ نَسْأَلُكَ الْعَافِيَةَ مِنْ كُلِّ بَلِيَّةٍ نَسْأَلُكَ الْعَافِيَةَ مِنْ كُلِّ بَلِيَّةٍ وَالسَّلَامَةَ مِنْ كُلِّ رَزِيَّةٍ يَا رَبَّ كُلِّ الْبَرِيَّةِ.\nاللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ وَتَحَوُّلِ عَافِيَتِكَ وَفُجَاءَةِ نِقْمَتِكَ وَجَمِيعِ سَخَطِكَ.\nاللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنَ الطَّعْنِ وَالطَّاعُونِ وَالْوَبَاءِ وَعُمُومِ الْبَلَاءِ.\nاللَّهُمَّ وَفِّقْ إِمَامَنَا وَلِيَّ عَهْدِهِ، وَأَعْوَانَهُمْ لِكُلِّ مَا تُحِبُّ وَتَرْضَى، وَكُنْ لَهُمْ عَوْنًا وَنَصِيرًا وَمُؤَيِّدًا وَظَهِيرًا.\nاللَّهُمَّ احْفَظْ رِجَالَ أَمْنِنَا وَجُنُودَنَا عَلَى ثُغُورِنَا وَالْقَائِمِينَ عَلَى صِحَّتِنَا.\nاللَّهُمَّ اجْزِهِمْ عَنَّا وَعَنِ الْمُسْلِمِينَ خَيْرَ الْجَزَاءِ اللَّهُمَّ تَقَبَّلْ مِنَّا؛ إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ، وَاغْفِرْ لَنَا إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ، وَتُبْ عَلَيْنَا، إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ وَصَلِّ اللَّهُمَّ وَسَلِّمْ وَبَارِكْ عَلَى نَبِيِّنَا مُحَمَّدٍ وَعَلَى آلِهِ وَصَحْبِهِ أَجْمَعِينَ.",
        "note": "الشيخ ياسر الدوسري",
