        "itemNumber": 325,
        "text": "لَا إِلَهَ إِلَّا اللَّهُ الْعَظِيمُ الْحَلِيمُ لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْكَرِيمِ لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَاوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْعَظِيمِ لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ مَا عَبَدْنَاكَ حَقَّ عِبَادَتِكَ وَلَا شَكَرْنَاكَ حَقَّ شُكْرِكَ وَلَا قَدَرْنَاكَ حَقَّ قَدْرِكَ لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنَّا كُنَّا مِنَ الظَّالِمِينَ وَإِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ.\nاللَّهُمَّ لَكَ أَسْلَمْنَا، وَبِكَ آمَنَّا وَمَا أَسْرَرْنَا وَمَا أَعْلَنَّا، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنَّا.\nاللَّهُمَّ يَا فَارِجَ الْهَمِّ، يَا كَاشِفَ الْغَمِّ، يَا رَحْمَنُ الدُّنْيَا وَالْآخِرَةِ وَرَحِيمَهُمَا نَسْأَلُكَ رَحْمَةً مِنْ عِنْدِكَ تُغْنِينَا عَنْ رَحْمَةِ مَنْ سِوَاكَ يَا خَفِيَّ الْأَلْطَافِ نَجِّنَا مِمَّا نَخَافُ نَجِّنَا مِمَّا نَخَافُ إِلَهَنَا وَسَيِّدَنَا.\nاللَّهُمَّ إِنَّا نَسْتَدْفِعُ بِكَ هَذَا الْوَبَاءَ، اللَّهُمَّ إِنَّا نَسْتَدْفِعُ بِكَ هَذَا الْوَبَاءَ وَنَعُوذُ بِكَ مِنْ كُلِّ الدَّاءِ وَنَسْتَجِيرُ بِكَ مِنَ الْبَلَاءِ يَا رَبَّ الْأَرْضِ وَالسَّمَاءِ.\nاللَّهُمَّ اصْرِفْ هَذَا الْبَلَاءَ عَنْ بِلَادِنَا وَعَنْ كُلِّ بِلَادِ الْعَالَمِ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنَ الْبَرَصِ، وَالْجُنُونِ، وَالْجُذَامِ، وَمِنْ سَيِّئِ الْأَسْقَامِ.\nاللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنَ الطَّعْنِ وَالطَّاعُونِ وَالْوَبَاءِ وَمِنْ عُمُومِ الْبَلَاءِ.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِنَا وَدُنْيَانَا وَأَهْلِينَا وَأَمْوَالِنَا.\nاللَّهُمَّ اسْتُرْ عَوْرَاتِنَا وَآمِنْ رَوْعَاتِنَا، وَاحْفَظْنَا مِنْ بَيْنِ أَيْدِينَا، وَمِنْ خَلْفِنَا، وَعَنْ أَيْمَانِنَا وَعَنْ شَمَائِلِنَا، وَمِنْ فَوْقِنَا، وَنَعُوذُ بِكَ.\nرَبَّنَا أَنْ نُغْتَالَ مِنْ تَحْتِنَا اللَّهُمَّ فَرِّجْ هُمُومَنَا، وَنَفِّسْ كُرُوبَنَا وَاقْضِ دُيُونَنَا وَاشْفِ مَرْضَانَا وَعَافِ مُبْتَلَانَا، وَارْحَمْ مَوْتَانَا، وَاقْبَلْ صِيَامَنَا وَقِيَامَنَا، وَفِّقْ أَوْلَادَنَا وَجُنُودَنَا عَلَى ثُغُورِنَا، وَفِّقْ الْقَائِمِينَ عَلَى شُؤُونِ صِحَّتِنَا يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ وَفِّقْ خَادِمَ الْحَرَمَيْنِ الشَّرِيفَيْنِ لِكُلِّ مَا تُحِبُّ وَتَرْضَى، وَهَيِّئْ لَهُ الْبِطَانَةَ الصَّالِحَةَ الَّتِي تَدُلُّهُ عَلَى الْخَيْرِ وَتُعِينُهُ عَلَيْهِ، وَفِّقْ وَلِيَّ عَهْدِهِ لِكُلِّ مَا تُحِبُّ وَتَرْضَى وَلِكُلِّ مَا فِيهِ صَلَاحٌ لِلْبِلَادِ وَالْعِبَادِ وَلِكُلِّ مَا فِيهِ عِزٌّ وَنَصْرٌ وَتَمْكِينٌ لِلْإِسْلَامِ وَالْمُسْلِمِينَ بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِينَ.\nاللَّهُمَّ مَا سَأَلْنَاكَ مِنْ خَيْرٍ فَأَعْطِنَاهُ وَمَا لَمْ نَسْأَلُكَ فَابْتَدِئْنَا وَمَا قَصُرَتْ عَنْهُ آمَالُنَا وَأَعْمَالُنَا مِنْ خَيْرِ الدُّنْيَا وَالْآخِرَةِ فَبَلِّغْنَا إِيَّاهُ وَصَلِّ اللَّهُمَّ وَسَلِّمْ وَبَارِكْ عَلَى نَبِيِّنَا مُحَمَّدٍ وَعَلَى آلِهِ وَصَحْبِهِ أَجْمَعِينَ.",
        "note": "الشيخ ياسر الدوسري",
