        "text": "اللَّهُمَّ اهْدِنَا فِيمَنْ هَدَيْتَ، وَعَافِنَا فِيمَنْ عَافَيْتَ، وَتَوَلَّنَا فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لَنَا فِيمَا أَعْطَيْتَ، وَقِنَا بِعِزَّتِكَ شَرَّ مَا قَضَيْتَ؛ فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ. تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ. لَكَ الْحَمْدُ عَلَى مَا قَضَيْتَ، وَلَكَ الشُّكْرُ عَلَى مَا أَعْطَيْتَ. نَسْتَغْفِرُكَ اللَّهُمَّ مِنْ جَمِيعِ الذُّنُوبِ وَالْخَطَايَا، وَنَتُوبُ إِلَيْكَ.\nرَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ، وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلًّا لِلَّذِينَ آمَنُوا، رَبَّنَا إِنَّكَ رَؤُوفٌ رَحِيمٌ.\nرَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا، وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً، إِنَّكَ أَنْتَ الْوَهَّابُ.\nرَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا، وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً، إِنَّكَ أَنْتَ الْوَهَّابُ.\nاللَّهُمَّ يَا عَفُوُّ، يَا غَفُورُ، ارْحَمْ أَمْوَاتَ الْمُسْلِمِينَ، وَاغْفِرْ لَهُمْ أَجْمَعِينَ، وَعَافِهِمْ وَاعْفُ عَنْهُمْ، وَأَكْرِمْ نُزُلَهُمْ، وَوَسِّعْ مُدْخَلَهُمْ، وَاغْسِلْهُمْ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِمْ مِنَ الذُّنُوبِ وَالْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ.\nاللَّهُمَّ أَحْسِنْ وُقُوفَنَا بَيْنَ يَدَيْكَ، وَلَا تُخْزِنَا يَوْمَ الْعَرْضِ عَلَيْكَ.\nاللَّهُمَّ أَحْسِنْ وُقُوفَنَا بَيْنَ يَدَيْكَ، وَلَا تُخْزِنَا يَوْمَ الْعَرْضِ عَلَيْكَ.\nاللَّهُمَّ تَقَبَّلْ صَلَاتَنَا وَصِيَامَنَا وَقِيَامَنَا وَسُجُودَنَا وَرُكُوعَنَا.\nاللَّهُمَّ اجْعَلْنَا مِنْ عُتَقَائِكَ مِنَ النَّارِ.\nاللَّهُمَّ اجْعَلْنَا مِنْ عُتَقَائِكَ مِنَ النَّارِ.\nاللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا.\nاللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا.\nاللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا.\nفَاعْفُ عَنَّا يَا كَرِيمُ، فَاعْفُ عَنَّا يَا رَحِيمُ، فَاعْفُ عَنَّا يَا كَرِيمُ، يَا أَكْرَمَ الْأَكْرَمِينَ.\nاللَّهُمَّ اجْعَلْنَا يَا مَوْلَانَا فِي شَهْرِنَا هَذَا، وَفِي يَوْمِنَا هَذَا، وَفِي لَيْلَتِنَا هَذِهِ، مِنْ عُتَقَائِكَ مِنَ النَّارِ، وَاجْعَلْنَا مِنَ الْمَقْبُولِينَ الْفَائِزِينَ بِرَحْمَتِكَ، يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنَ الْمَوْتِ وَكَرْبَتِهِ، وَالْقَبْرِ وَغُمَّتِهِ، وَالصِّرَاطِ وَزَلَّتِهِ، وَيَوْمِ الْقِيَامَةِ وَرَوْعَتِهِ.\nاللَّهُمَّ اجْعَلْنَا نَخْشَاكَ كَأَنَّا نَرَاكَ، وَأَسْعِدْنَا بِتَقْوَاكَ، وَمَتِّعْنَا بِرُؤْيَاكَ، وَاجْمَعْنَا مَعَ نَبِيِّكَ وَمُصْطَفَاكَ.\nاللَّهُمَّ اجْعَلْنَا نَخْشَاكَ كَأَنَّا نَرَاكَ، وَأَسْعِدْنَا بِتَقْوَاكَ، وَمَتِّعْنَا بِرُؤْيَاكَ، وَاجْمَعْنَا مَعَ نَبِيِّكَ وَمُصْطَفَاكَ.\nاللَّهُمَّ انْصُرِ الْإِسْلَامَ وَأَعِزَّ الْمُسْلِمِينَ، اللَّهُمَّ انْصُرِ الْإِسْلَامَ وَأَعِزَّ الْمُسْلِمِينَ، وَأَعْلِ بِفَضْلِكَ كَلِمَةَ الْحَقِّ وَالدِّينِ.\nاللَّهُمَّ أَهْلِكِ الْكُفَّارَ وَمَنْ وَالَاهُمْ، اللَّهُمَّ أَهْلِكِ الْكُفَّارَ وَمَنْ وَالَاهُمْ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ لَا تَدَعْ لَنَا ذَنْبًا إِلَّا غَفَرْتَهُ، وَلَا هَمًّا إِلَّا فَرَّجْتَهُ، وَلَا دَيْنًا إِلَّا قَضَيْتَهُ، وَلَا مَرِيضًا إِلَّا شَفَيْتَهُ، وَلَا حَاجَةً مِنْ حَوَائِجِ الدُّنْيَا وَالْآخِرَةِ إِلَّا قَضَيْتَهَا، يَا أَرْحَمَ الرَّاحِمِينَ.\nاللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ.\nاللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ.",
        "note": "الشيخ قادر الكردي",
