        "text": "اللَّهُمَّ اهْدِنَا فِيمَنْ هَدَيْتَ، وَعَافِنَا فِيمَنْ عَافَيْتَ، وَتَوَلَّنَا فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لَنَا فِيمَا أَعْطَيْتَ، وَقِنَا بِعِزَّتِكَ شَرَّ مَا قَضَيْتَ؛ فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ.\nتَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ.\nلَكَ الْحَمْدُ عَلَى مَا قَضَيْتَ، وَلَكَ الشُّكْرُ عَلَى مَا أَعْطَيْتَ.\nنَسْتَغْفِرُكَ اللَّهُمَّ مِنْ جَمِيعِ الذُّنُوبِ وَالْخَطَايَا، وَنَتُوبُ إِلَيْكَ.\nاللَّهُمَّ اغْفِرْ لَنَا مَا قَدَّمْنَا وَمَا أَخَّرْنَا، وَمَا أَسْرَرْنَا وَمَا أَعْلَنَّا، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنَّا؛ إِنَّكَ أَنْتَ السَّمِيعُ الْقَرِيبُ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا، اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا، فَاعْفُ عَنَّا يَا كَرِيمُ، فَاعْفُ عَنَّا يَا رَحِيمُ، فَاعْفُ عَنَّا يَا أَكْرَمَ الْأَكْرَمِينَ.\nيَا اللَّهُ، يَا اللَّهُ، يَا صَمَدُ، يَا مَنْ لَمْ يَلِدْ وَلَمْ يُولَدْ، وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ.\nاللَّهُمَّ اجْعَلْنَا مِنْ عُتَقَائِكَ مِنَ النَّارِ.\nاللَّهُمَّ اجْعَلْنَا مِنْ عُتَقَاءِ شَهْرِ رَمَضَانَ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ تَقَبَّلْ صِيَامَنَا وَقِيَامَنَا وَرُكُوعَنَا وَسُجُودَنَا لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنَّا كُنَّا مِنَ الظَّالِمِينَ، لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنَّا كُنَّا مِنَ الظَّالِمِينَ.\nرَبَّنَا اغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِي أَمْرِنَا، وَثَبِّتْ أَقْدَامَنَا وَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ.\nاللَّهُمَّ ارْفَعْ مَقْتَكَ وَغَضَبَكَ عَنَّا وَلَا تُؤَاخِذْنَا بِمَا فَعَلْنَا وَلَا بِمَا فَعَلَ السُّفَهَاءُ مِنَّا وَلَا تُسَلِّطْ عَلَيْنَا يَا رَبَّنَا، بِذُنُوبِنَا مَنْ لَا يَخَافُكَ وَلَا يَخْشَاكَ وَلَا يَرْحَمُنَا.\nاللَّهُمَّ أَلِّفْ بَيْنَ قُلُوبِنَا، وَاخْتِمْ بِالْبَاقِيَاتِ الصَّالِحَاتِ أَعْمَالَنَا وَاجْعَلِ بِلَادَنَا آمِنَةً مُطْمَئِنَّةً سَخَاءً رَخَاءً، وَسَائِرَ بِلَادِ الْمُسْلِمِينَ.\nاللَّهُمَّ انْصُرِ الْإِسْلَامَ وَأَعِزَّ الْمُسْلِمِينَ، اللَّهُمَّ انْصُرِ الْإِسْلَامَ وَأَعِزَّ الْمُسْلِمِينَ وَأَذِلَّ الشِّرْكَ وَالْمُشْرِكِينَ، وَدَمِّرْ أَعْدَاءَ الدِّينِ، وَانْصُرْ عِبَادَكَ الْمُوَحِّدِينَ فِي كُلِّ أَرْضٍ يُذْكَرُ فِيهَا اسْمَكَ وَفِي كُلِّ مَكَانٍ.\nاللَّهُمَّ أَغْنِنَا بِحَلَالِكَ عَنْ حَرَامِكَ وَبِطَاعَتِكَ عَنْ مَعْصِيَتِكَ وَبِفَضْلِكَ وَجُودِكَ وَكَرَمِكَ عَمَّنْ سِوَاكَ وَارْحَمْنَا رَحْمَةً تُغْنِينَا بِهَا عَنْ رَحْمَةِ مَنْ سِوَاكَ يَا أَكْرَمَ الْأَكْرَمِينَ، أَعْطِنَا وَلَا تَحْرِمْنَا أَكْرِمْنَا وَلَا تُهِنَّا زِدْنَا وَلَا تَنْقُصْنَا أَعِنَّا وَلَا تُعِنْ عَلَيْنَا انْصُرْنَا وَلَا تَنْصُرْ عَلَيْنَا انْصُرْنَا عَلَى أَنْفُسِنَا رُدَّنَا إِلَى دِينِكَ رَدًّا جَمِيلًا يَا أَرْحَمَ الرَّاحِمِينَ.\nيَا أَكْرَمَ الْأَكْرَمِينَ.\nاللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ.\nاللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ.",
