        "text": "اللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ نُورُ السَّمَاوَاتِ وَالْأَرْضِ وَمَنْ فِيهِنَّ وَلَكَ الْحَمْدُ أَنْتَ قَيِّمُ السَّمَاوَاتِ وَالْأَرْضِ وَمَنْ فِيهِنَّ وَلَكَ الْحَمْدُ أَنْتَ فَاطِرُ السَّمَاوَاتِ وَالْأَرْضِ وَمَنْ فِيهِنَّ وَلَكَ الْحَمْدُ أَنْتَ الْحَقُّ، وَوَعْدُكَ حَقٌّ وَلِقَاؤُكَ حَقٌّ وَالْجَنَّةُ حَقٌّ وَالنَّارُ حَقٌّ وَالسَّاعَةُ حَقٌّ وَالنَّبِيُّونَ حَقٌّ وَمُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَقٌّ أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ، لَا إِلَهَ إِلَّا أَنْتَ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ تَمَّ نُورُكَ فَهَدَيْتَ فَلَكَ الْحَمْدُ وَعَظُمَ حِلْمُكَ فَعَفَوْتَ فَلَكَ الْحَمْدُ بَسَطْتَ يَدَكَ فَأَعْطَيْتَ فَلَكَ الْحَمْدُ رَبَّنَا، وَجْهُكَ أَكْرَمُ الْوُجُوهِ، وَجَاهُكَ أَعْظَمُ الْجَاهِ وَعَطِيَّتُكَ أَفْضَلُ الْعَطِيَّةِ وَأَهْنَؤُهَا. تُطَاعُ فَتَشْكُرُ وَتُعْصَى فَتَغْفِرُ وَتُجِيبُ الْمُضْطَرَّ وَتَكْشِفُ الضُّرَّ وَتَشْفِي السَّقِيمَ وَتَغْفِرُ الذَّنْبَ الْعَظِيمَ وَأَنْتَ الرَّؤُوفُ الرَّحِيمُ سُبْحَانَكَ مَا عَبَدْنَاكَ حَقَّ عِبَادَتِكَ وَلَا شَكَرْنَاكَ حَقَّ شُكْرِكَ وَلَا قَدَرْنَاكَ حَقَّ قَدْرِكَ لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنَّا كُنَّا مِنَ الظَّالِمِينَ وَإِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا، لَنَكُونَنَّ مِنَ الْخَاسِرِينَ.\nاللَّهُمَّ أَنْتَ رَبُّنَا لَا إِلَهَ إِلَّا أَنْتَ خَلَقْتَنَا وَنَحْنُ عَبِيدُكَ وَنَحْنُ عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْنَا نَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْنَا نَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيْنَا وَنَبُوءُ بِذُنُوبِنَا فَاغْفِرْ لَنَا.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ وَنَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِنَا وَدُنْيَانَا وَأَهْلِينَا وَأَمْوَالِنَا.\nاللَّهُمَّ اسْتُرْ عَوْرَاتِنَا وَآمِنْ رَوْعَاتِنَا، وَاحْفَظْنَا مِنْ بَيْنِ أَيْدِينَا، وَمِنْ خَلْفِنَا، وَعَنْ أَيْمَانِنَا، وَعَنْ شَمَائِلِنَا، وَمِنْ فَوْقِنَا، وَنَعُوذُ بِعَظَمَتِكَ أَنْ نُغْتَالَ مِنْ تَحْتِنَا.\nاللَّهُمَّ أَلْزِمْ قُلُوبَنَا حِفْظَ كِتَابِكَ وَتِلَاوَتِهِ آنَاءَ اللَّيْلِ وَأَطْرَافَ النَّهَارِ عَلَى الْوَجْهِ الَّذِي يُرْضِيكَ عَنَّا.\nاللَّهُمَّ ارْزُقْنَا مِنَ الْفَهْمِ عَنْكَ وَعَنْ رَسُولِكَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا يُبَلِّغُنَا دَرَجَةَ الصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ وَحَسُنَ أُولَئِكَ رَفِيقًا يَا مُعَلِّمَ إِبْرَاهِيمَ عِلْمِنَا وَيَا مُفَهِّمَ سُلَيْمَانَ فَهِّمْنَا.\nاللَّهُمَّ اجْعَلْنَا مَفَاتِيحَ لِلْخَيْرِ مَغَالِيقَ لِلشَّرِّ فِي كُلِّ مَا كَانَ يَا حَيُّ يَا قَيُّومُ، أَصْلِحْ لَنَا شَأْنَنَا كُلَّهُ وَلَا تَكِلْنَا إِلَى أَنْفُسِنَا طَرْفَةَ عَيْنٍ.\nاللَّهُمَّ فَرِّجْ هُمُومَنَا وَنَفِّسْ كُرُوبَنَا وَاقْضِ دُيُونَنَا وَاشْفِ مَرْضَانَا، وَاغْفِرْ لِمَوْتَانَا وَمَوْتَى الْمُسْلِمِينَ، بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِينَ.\nاللَّهُمَّ أَعِزَّ الْإِسْلَامَ وَالْمُسْلِمِينَ وَأَذِلَّ الشِّرْكَ وَالْمُشْرِكِينَ وَاحْمِ حَوْزَةَ الدِّينِ.\nاللَّهُمَّ انْصُرْ إِخْوَانَنَا الْمُوَحِّدِينَ فِي كُلِّ مَكَانٍ اللَّهُمَّ يَا جَابِرَ السَّمَاوَاتِ وَالْأَرْضِ اجْبُرْ قُلُوبَنَا وَقُلُوبَ الْمُسْلِمِينَ جَبْرًا يَلِيقُ بِجَلَالِ وَجْهِكَ وَعَظِيمِ سُلْطَانِكَ.\nاللَّهُمَّ انْصُرِ الْإِسْلَامَ وَالْمُسْلِمِينَ فِي كُلِّ مَكَانٍ اللَّهُمَّ آمِنَّا فِي أَوْطَانِنَا، وَأَصْلِحْ أَئِمَّتَنَا وَوُلَاةَ أُمُورِنَا، وَوَفِّقْ وَلِيَّ أَمْرِنَا لِكُلِّ مَا تُحِبُّ وَتَرْضَى، وَكُنْ لَهُ عَوْنًا فِي كُلِّ مَا أَهَمَّهُ، وَاجْمَعْ بِهِ كَلِمَةَ الْأُمَّةِ، وَانْصُرْ بِهِ الْكِتَابَ وَالسُّنَّةَ وَوَفِّقْهُ وَنَائِبَهُ وَأَعْوَانِهِ لِكُلِّ مَا فِيهِ صَلَاحٌ لِلْبِلَادِ وَالْعِبَادِ وَلِكُلِّ مَا فِيهِ نَصْرٍ وَعِزٍّ وَتَمْكِينٍ لِلْإِسْلَامِ وَالْمُسْلِمِينَ.\nاللَّهُمَّ أَصْلِحْ نِسَاءَنَا وَأَوْلَادِنَا وَشَبَابَنَا وَفَتَيَاتِنَا وَأَرِنَا، وَإِيَّاهُمُ الْحَقَّ حَقًّا وَارْزُقْنَا اتِّبَاعَهُ وَأَرِنَا، وَإِيَّاهُمْ الْبَاطِلَ بَاطِلًا وَارْزُقْنَا اجْتِنَابَهُ، بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِينَ.\nاللَّهُمَّ تَقَبَّلْ مِنَّا؛ إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ، وَاغْفِرْ لَنَا إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ، وَتُبْ عَلَيْنَا، إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ سُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَ وَسَلَامٌ عَلَى الْمُرْسَلِينَ، وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ وَصَلِّ اللَّهُمَّ وَسَلِّمْ وَبَارِكْ عَلَى نَبِيِّهِ مُحَمَّدٍ وَعَلَى آلِهِ وَصَحْبِهِ أَجْمَعِينَ.",
