        "text": "اللَّهُمَّ اهْدِنَا فِيمَنْ هَدَيْتَ، وَعَافِنَا فِيمَنْ عَافَيْتَ، وَتَوَلَّنَا فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لَنَا فِيمَا أَعْطَيْتَ، وَقِنَا بِعِزَّتِكَ شَرَّ مَا قَضَيْتَ؛ فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ.\nتَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ.\nلَكَ الْحَمْدُ عَلَى مَا قَضَيْتَ، وَلَكَ الشُّكْرُ عَلَى مَا أَعْطَيْتَ.\nنَسْتَغْفِرُكَ اللَّهُمَّ مِنْ جَمِيعِ الذُّنُوبِ وَالْخَطَايَا، وَنَتُوبُ إِلَيْكَ.\nاللَّهُمَّ اقْسِمْ لَنَا مِنْ خَشْيَتِكَ مَا تَحُولُ بِهِ بَيْنَنَا وَبَيْنَ مَعْصِيَتِكَ، وَمِنْ طَاعَتِكَ مَا تُبَلِّغُنَا بِهِ جَنَّتَكَ، وَمِنَ الْيَقِينِ مَا تُهَوِّنُ بِهِ عَلَيْنَا مَصَائِبَ الدُّنْيَا.\nوَمَتِّعْنَا اللَّهُمَّ بِأَسْمَاعِنَا وَأَبْصَارِنَا وَقُوَّاتِنَا أَبَدًا مَا أَبْقَيْتَنَا، وَاجْعَلْهُ الْوَارِثَ مِنَّا، وَاجْعَلْ ثَأْرَنَا عَلَى مَنْ ظَلَمَنَا، وَانْصُرْنَا عَلَى مَنْ عَادَانَا.\nوَلَا تَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّنَا، وَلَا مَبْلَغَ عِلْمِنَا، وَلَا إِلَى النَّارِ مَصِيرَنَا.\nوَاجْعَلِ اللَّهُمَّ الْجَنَّةَ دَارَنَا وَقَرَارَنَا، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا، فَاعْفُ عَنَّا يَا كَرِيمُ، فَاعْفُ عَنَّا يَا رَحِيمُ، فَاعْفُ عَنَّا يَا أَكْرَمَ الْأَكْرَمِينَ.\nاللَّهُمَّ اغْفِرْ لَنَا مَا قَدَّمْنَا وَمَا أَخَّرْنَا، وَمَا أَسْرَرْنَا وَمَا أَعْلَنَّا، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنَّا؛ إِنَّكَ أَنْتَ السَّمِيعُ الْقَرِيبُ، إِنَّكَ أَنْتَ السَّمِيعُ الْقَرِيبُ.\nاللَّهُمَّ اشْفِ مَرْضَانَا، وَارْحَمْ مَوْتَانَا، وَفُكَّ أَسْرَانَا.\nكَمَا نَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى، كَمَا نَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى.\nاللَّهُمَّ تَقَبَّلْ صِيَامَنَا وَقِيَامَنَا وَسُجُودَنَا وَرُكُوعَنَا، بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِينَ.\nاللَّهُمَّ اجْعَلِ الْقُرْآنَ الْعَظِيمَ رَبِيعَ قُلُوبِنَا، وَنُورَ صُدُورِنَا، وَجَلَاءَ أَحْزَانِنَا، وَذَهَابَ هُمُومِنَا وَغُمُومِنَا، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ ارْحَمْنَا بِالْقُرْآنِ، وَاجْعَلْهُ لَنَا إِمَامًا وَنُورًا وَهُدًى وَرَحْمَةً.\nاللَّهُمَّ ذَكِّرْنَا مِنْهُ مَا نَسِينَا، وَعَلِّمْنَا مِنْهُ مَا جَهِلْنَا، وَارْزُقْنَا تِلَاوَتَهُ آنَاءَ اللَّيْلِ وَأَطْرَافَ النَّهَارِ، وَاجْعَلْهُ لَنَا حُجَّةً، يَا رَبَّ الْعَالَمِينَ، وَاجْعَلْهُ لَنَا حُجَّةً، يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ عِيشَةً هَنِيَّةً وَمِيتَةً سَوِيَّةً، وَمَرَدًّا غَيْرَ مُخْزٍ وَلَا فَاضِحٍ.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ خَيْرَ الْمَسْأَلَةِ، وَخَيْرَ الدُّعَاءِ، وَخَيْرَ النَّجَاحِ، وَخَيْرَ الْعِلْمِ، وَخَيْرَ الْعَمَلِ، وَخَيْرَ الثَّوَابِ، وَخَيْرَ الْحَيَاةِ، وَخَيْرَ الْمَمَاتِ.\nاللَّهُمَّ ثَبِّتْنَا وَثَقِّلْ مَوَازِينَنَا، وَحَقِّقْ إِيمَانَنَا، وَارْفَعْ دَرَجَتَنَا، وَتَقَبَّلْ صَلَاتَنَا، وَاغْفِرْ خَطِيئَاتِنَا، وَنَسْأَلُكَ الْعُلَا مِنَ الْجَنَّةِ.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ، وَعَزَائِمَ مَغْفِرَتِكَ، وَالسَّلَامَةَ مِنْ كُلِّ إِثْمٍ، وَالْغَنِيمَةَ مِنْ كُلِّ بِرٍّ، وَالْفَوْزَ بِالْجَنَّةِ، وَالنَّجَاةَ مِنَ النَّارِ.\nاللَّهُمَّ لَا تَدَعْ لَنَا ذَنْبًا إِلَّا غَفَرْتَهُ، وَلَا هَمًّا إِلَّا فَرَّجْتَهُ، وَلَا دَيْنًا إِلَّا قَضَيْتَهُ، وَلَا حَاجَةً مِنْ حَوَائِجِ الدُّنْيَا وَالْآخِرَةِ إِلَّا قَضَيْتَهَا، يَا أَرْحَمَ الرَّاحِمِينَ، إِلَهَنَا وَخَالِقَنَا.\nاللَّهُمَّ انْصُرْ إِخْوَانَنَا الْمُسْتَضْعَفِينَ فِي كُلِّ مَكَانٍ مَا لَنَا سِوَاكَ نَرْجُوهُ مَا لَنَا سِوَاكَ نَدْعُوهُ، مَا لَنَا سِوَاكَ نَدْعُوهُ اسْتَجِبْ دُعَاءَنَا بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ احْفَظْ إِخْوَانِنَا الْمُسْتَضْعَفِينَ فِي كُلِّ مَكَانٍ بِرَحْمَتِكَ يَا عَزِيزُ يَا جَبَّارُ.\nاللَّهُمَّ احْفَظْ بَلَدَنَا هَذَا آمِنًا سَخَاءً رَخَاءً، وَسَائِرَ بِلَادِ الْمُسْلِمِينَ.\nرَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً، وَفِي الْآخِرَةِ حَسَنَةً، وَقِنَا عَذَابَ النَّارِ.\nاللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ.\nاللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ.",
