        "text": "اللَّهُمَّ اهْدِنَا فِيمَنْ هَدَيْتَ، وَعَافِنَا فِيمَنْ عَافَيْتَ، وَتَوَلَّنَا فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لَنَا فِيمَا أَعْطَيْتَ، وَقِنَا وَاصْرِفْ عَنَّا شَرَّ مَا قَضَيْتَ، فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ.\nتَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ.\nلَكَ الْحَمْدُ عَلَى مَا قَضَيْتَ، وَلَكَ الشُّكْرُ عَلَى مَا أَعْطَيْتَ.\nنَسْتَغْفِرُكَ اللَّهُمَّ مِنْ جَمِيعِ الذُّنُوبِ وَالْخَطَايَا، وَنَتُوبُ إِلَيْكَ.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ، وَعَزَائِمَ مَغْفِرَتِكَ، وَالسَّلَامَةَ مِنْ كُلِّ إِثْمٍ، وَالْغَنِيمَةَ مِنْ كُلِّ بِرٍّ، وَالْفَوْزَ بِالْجَنَّةِ، وَالنَّجَاةَ مِنَ النَّارِ.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ فِي دِينِنَا وَدُنْيَانَا وَأَهْلِينَا.\nاللَّهُمَّ اسْتُرْ عَوْرَاتِنَا وَآمِنْ رَوْعَاتِنَا، وَاحْفَظْنَا مِنْ بَيْنِ أَيْدِينَا، وَمِنْ خَلْفِنَا، وَعَنْ أَيْمَانِنَا، وَعَنْ شَمَائِلِنَا، وَمِنْ فَوْقِنَا، وَنَعُوذُ بِعَظَمَتِكَ أَنْ نُغْتَالَ مِنْ تَحْتِنَا.\nاللَّهُمَّ يَا فَارِجَ الْهَمِّ، يَا كَاشِفَ الْغَمِّ، يَا رَحْمَنُ الدُّنْيَا وَالْآخِرَةِ وَرَحِيمَهُمَا نَسْأَلُكَ رَحْمَةً مِنْ عِنْدِكَ تُغْنِينَا عَنْ رَحْمَةِ مَنْ سِوَاكَ يَا حَيُّ يَا قَيُّومُ، بِرَحْمَتِكَ نَسْتَغِيثُ، أَصْلِحْ لَنَا شَأْنَنَا كُلَّهُ وَلَا تَكِلْنَا إِلَى أَنْفُسِنَا طَرْفَةَ عَيْنٍ، بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِينَ.\nاللَّهُمَّ أَعِزَّ الْإِسْلَامَ وَالْمُسْلِمِينَ وَأَذِلَّ الشِّرْكَ وَالْمُشْرِكِينَ وَاحْمِ حَوْزَةَ الدِّينِ وَاجْعَلْ هَذَا الْبَلَدَ آمِنًا مُطْمَئِنًّا رَخَاءً، وَسَائِرَ بِلَادِ الْمُسْلِمِينَ.\nاللَّهُمَّ مَنْ أَرَادَنَا وَأَرَادَ بِلَادَنَا بِسُوءٍ أَوْ فِتْنَةٍ أَوْ تَفْجِيرٍ أَوْ تَكْفِيرٍ فَأَشْغِلْهُ فِي نَفْسِهِ وَاجْعَلِ تَدْبِيرَهُ تَدْمِيرًا عَلَيْهِ يَا قَوِيُّ يَا عَزِيزُ، إِنَّا نَدْرَأُ بِكَ فِي نَحْرِهِ وَنَعُوذُ بِكَ مِنْ شَرِّهِ.\nاللَّهُمَّ اكْفِنَاهُ بِمَا شِئْتَ اللَّهُمَّ، وَفِّقْ وَلِيَّ أَمْرِنَا بِتَوْفِيقِكَ وَأَيِّدْهُ بِتَأْيِيدِكَ، وَهَيِّئْ لَهُ الْبِطَانَةَ الصَّالِحَةَ النَّاصِحَةَ الَّتِي تَدُلُّهُ عَلَى الْخَيْرِ وَتُعِينُهُ عَلَيْهِ وَوَفِّقْهُ وَوَلِيَّ عَهْدِهِ، وَأَعْوَانَهُمْ لِكُلِّ مَا تُحِبُّ وَتَرْضَى وَلِكُلِّ مَا فِيهِ عِزٌّ وَنَصْرٌ وَتَمْكِينٌ لِلْإِسْلَامِ وَالْمُسْلِمِينَ، بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِينَ.\nاللَّهُمَّ احْفَظْ رِجَالَ أَمْنِنَا وَجُنُودَنَا عَلَى ثُغُورِنَا بِعَيْنِكَ الَّتِي لَا تَنَامُ وَبِرُكْنِكَ الَّذِي لَا يُضَامُ احْفَظْهُمْ مِنْ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ وَعَنْ أَيْمَانِهِمْ وَعَنْ شَمَائِلِهِمْ وَمِنْ فَوْقِهِمْ وَنَعُوذُ بِكَ أَنْ يُغْتَالُوا مِنْ تَحْتِهِمُ، بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِينَ.\nاللَّهُمَّ هَذَا الدُّعَاءُ وَمِنْكَ الْإِجَابَةُ، وَهَذَا الْجُهْدُ وَعَلَيْكَ التُّكْلَانُ.\nسُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَ، وَسَلَامٌ عَلَى الْمُرْسَلِينَ، وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ.\nوَصَلِّ اللَّهُمَّ وَسَلِّمْ وَبَارِكْ عَلَى نَبِيِّنَا مُحَمَّدٍ وَعَلَى آلِهِ وَصَحْبِهِ أَجْمَعِينَ.",
