        "itemNumber": 343,
        "text": "اللَّهُمَّ اهْدِنَا فِيمَنْ هَدَيْتَ، وَعَافِنَا فِيمَنْ عَافَيْتَ، وَتَوَلَّنَا فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لَنَا فِيمَا أَعْطَيْتَ، وَقِنَا بِعِزَّتِكَ شَرَّ مَا قَضَيْتَ؛ فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ.\nتَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ.\nلَكَ الْحَمْدُ عَلَى مَا قَضَيْتَ، وَلَكَ الشُّكْرُ عَلَى مَا أَعْطَيْتَ.\nنَسْتَغْفِرُكَ اللَّهُمَّ مِنْ جَمِيعِ الذُّنُوبِ وَالْخَطَايَا، وَنَتُوبُ إِلَيْكَ.\nاللَّهُمَّ اقْسِمْ لَنَا مِنْ خَشْيَتِكَ مَا تَحُولُ بِهِ بَيْنَنَا وَبَيْنَ مَعْصِيَتِكَ، وَمِنْ طَاعَتِكَ مَا تُبَلِّغُنَا بِهِ جَنَّتَكَ، وَمِنَ الْيَقِينِ مَا تُهَوِّنُ بِهِ عَلَيْنَا مَصَائِبَ الدُّنْيَا.\nوَمَتِّعْنَا اللَّهُمَّ بِأَسْمَاعِنَا وَأَبْصَارِنَا وَقُوَّاتِنَا أَبَدًا مَا أَبْقَيْتَنَا، وَاجْعَلْهُ الْوَارِثَ مِنَّا، وَاجْعَلْ ثَأْرَنَا عَلَى مَنْ ظَلَمَنَا، وَانْصُرْنَا عَلَى مَنْ عَادَانَا، وَلَا تَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّنَا، وَلَا مَبْلَغَ عِلْمِنَا، وَلَا إِلَى النَّارِ مَصِيرَنَا، وَلَا إِلَى النَّارِ مَصِيرَنَا.\nوَاجْعَلِ اللَّهُمَّ الْجَنَّةَ دَارَنَا وَقَرَارَنَا، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ يَا رَحْمَنُ، يَا ذَا الْجَلَالِ وَالْإِكْرَامِ نَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهِ، عَاجِلِهِ وَآجِلِهِ، مَا عَلِمْنَا مِنْهُ وَمَا لَمْ نَعْلَمْ، وَنَعُوذُ بِكَ مِنَ الشَّرِّ كُلِّهِ، عَاجِلِهِ وَآجِلِهِ، مَا عَلِمْنَا مِنْهُ وَمَا لَمْ نَعْلَمْ.\nاللَّهُمَّ مَتِّعْنَا بِالنَّظَرِ إِلَى وَجْهِكَ الْكَرِيمِ.\nرَبَّنَا تَقَبَّلْ مِنَّا؛ إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ، وَتُبْ عَلَيْنَا، إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ، وَاغْفِرْ لَنَا وَارْحَمْنَا إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ وَنَجِّنَا مِنَ الْغَمِّ وَالْهَمِّ وَالْكَرْبِ الْعَظِيمِ وَاجْعَلِ عِبَادَتَنَا خَالِصَةً لِوَجْهِكَ الْكَرِيمِ عَمَلًا بِقَوْلِكَ جَلَّ شَأْنُكَ فَمَنْ كَانَ يَرْجُو لِقَاءَ رَبِّهِ فَلْيَعْمَلْ عَمَلًا صَالِحًا وَلَا يُشْرِكْ بِعِبَادَةِ رَبِّهِ أَحَدًا.\nاللَّهُمَّ اجْعَلْنَا مِنَ الَّذِينَ إِذَا أَحْسَنُوا اسْتَبْشَرُوا وَإِذَا أَسَاءُوا اسْتَغْفَرُوا لَبَّيْكَ وَسَعْدَيْكَ وَالْخَيْرُ كُلُّهُ فِي يَدَيْكَ وَالشَّرُّ لَيْسَ إِلَيْكَ نَحْنُ مِنْكَ وَإِلَيْكَ تَبَارَكْتَ وَتَعَالَيْتَ نَسْتَغْفِرُكَ وَنَتُوبُ إِلَيْكَ.\nاللَّهُمَّ لَوْلَا أَنْتَ مَا اهْتَدَيْنَا اللَّهُمَّ يَا مُعْتِقَ الرِّقَابِ أَعْتِقْ رِقَابَنَا مِنَ النَّارِ، وَرِقَابَ آبَائِنَا وَأُمَّهَاتِنَا وَأَزْوَاجِنَا وَأَوْلَادِنَا وَبَنَاتِنَا، وَلِمَنْ كَانَ لَهُ حَقٌّ عَلَيْنَا وَرِقَابَ جَمِيعِ الْمُسْلِمِينَ وَالْمُسْلِمَاتِ، وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ، الْأَحْيَاءِ مِنْهُمْ وَالْأَمْوَاتِ.\nإِنَّكَ يَا مَوْلَانَا سَمِيعٌ قَرِيبٌ مُجِيبُ الدَّعَوَاتِ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ زِيَادَةً فِي الدِّينِ وَبَرَكَةً فِي الْعُمُرِ وَبَرَكَةً فِي الرِّزْقِ وَبَرَكَةً فِي الذُّرِّيَّةِ وَبَرَكَةً فِي الْوَالِدَيْنِ وَبَرَكَةً فِي الْأَعْمَالِ الصَّالِحَةِ وَنَسْأَلُكَ تَوْبَةً قَبْلَ الْمَوْتِ وَشَهَادَةً عِنْدَ الْمَوْتِ وَمَغْفِرَةً بَعْدَ الْمَوْتِ وَعَفْوًا عِنْدَ الْحِسَابِ وَأَمَانًا مِنَ الْعَذَابِ وَنَسْأَلُكَ نَصِيبًا مِنَ الْجَنَّةِ.\nاللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا، اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا.\nاللَّهُمَّ اشْفِ مَرْضَانَا، اللَّهُمَّ اشْفِ كُلَّ مَرِيضٍ وَعَافِ كُلَّ مُبْتَلًى، وَارْحَمْ مَوْتَانَا، وَفُكَّ أَسْرَانَا.\nكَمَا نَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى، بِرَحْمَتِكَ يَا أَكْرَمَ الْأَكْرَمِينَ.\nاللَّهُمَّ تَقَبَّلْ صَلَاتَنَا وَصِيَامَنَا وَسَائِرَ أَعْمَالِنَا بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ.\nاللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ.",
