        "itemNumber": 344,
        "text": "اللَّهُمَّ اهْدِنَا فِيمَنْ هَدَيْتَ، وَعَافِنَا فِيمَنْ عَافَيْتَ، وَتَوَلَّنَا فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لَنَا فِيمَا أَعْطَيْتَ، وَقِنَا وَاصْرِفْ عَنَّا شَرَّ مَا قَضَيْتَ، فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ.\nتَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ.\nلَكَ الْحَمْدُ عَلَى مَا قَضَيْتَ، وَلَكَ الشُّكْرُ عَلَى مَا أَعْطَيْتَ.\nنَسْتَغْفِرُكَ اللَّهُمَّ مِنْ جَمِيعِ الذُّنُوبِ وَالْخَطَايَا، وَنَتُوبُ إِلَيْكَ.\nاللَّهُمَّ اقْسِمْ لَنَا مِنْ خَشْيَتِكَ مَا تَحُولُ بِهِ بَيْنَنَا وَبَيْنَ مَعْصِيَتِكَ، وَمِنْ طَاعَتِكَ مَا تُبَلِّغُنَا بِهِ جَنَّتَكَ، وَمِنَ الْيَقِينِ مَا تُهَوِّنُ بِهِ عَلَيْنَا مَصَائِبَ الدُّنْيَا.\nوَمَتِّعْنَا اللَّهُمَّ بِأَسْمَاعِنَا وَأَبْصَارِنَا وَقُوَّاتِنَا أَبَدًا مَا أَبْقَيْتَنَا، وَاجْعَلْهُ الْوَارِثَ مِنَّا، وَاجْعَلْ ثَأْرَنَا عَلَى مَنْ ظَلَمَنَا، وَانْصُرْنَا عَلَى مَنْ عَادَانَا.\nوَلَا تَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّنَا، وَلَا مَبْلَغَ عِلْمِنَا، وَلَا إِلَى النَّارِ مَصِيرَنَا.\nوَاجْعَلِ الْجَنَّةَ هِيَ دَارَنَا وَقَرَارَنَا وَلَا تُسَلِّطْ عَلَيْنَا بِذُنُوبِنَا مَنْ لَا يَخَافُكَ فِينَا وَلَا يَرْحَمُنَا، بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِينَ.\nاللَّهُمَّ لَكَ الْحَمْدُ بِمَا خَلَقْتَنَا وَلَكَ الْحَمْدُ بِمَا عَلَّمْتَنَا وَلَكَ الْحَمْدُ بِمَا رَزَقْتَنَا وَلَكَ الْحَمْدُ بِمَا هَدَيْتَنَا وَلَكَ الْحَمْدُ بِمَا عَافَيْتَنَا لَكَ الْحَمْدُ بِالْإِسْلَامِ لَكَ الْحَمْدُ بِالْإِيمَانِ لَكَ الْحَمْدُ بِالْقُرْآنِ لَكَ الْحَمْدُ بِأَنْ بَلَّغْتَنَا رَمَضَانَ.\nاللَّهُمَّ وَفِّقْنَا لِصِيَامِ رَمَضَانَ وَقِيَامِهِ وَأَعِنَّا فِيهِ عَلَى الصِّيَامِ وَالْقِيَامِ وَوَفِّقْنَا لِقِيَامِ لَيْلَةِ الْقَدْرِ إِيمَانًا وَاحْتِسَابًا.\nاللَّهُمَّ اكْتُبْنَا فِيهِ مِنْ عِبَادِكَ الْمَقْبُولِينَ وَلَا تَجْعَلْنَا فِيهِ مِنْ عِبَادِكَ الْمَرْدُودِينَ الْخَاسِرِينَ.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهِ، عَاجِلِهِ وَآجِلِهِ، مَا عَلِمْنَا مِنْهُ وَمَا لَمْ نَعْلَمْ، وَنَعُوذُ بِكَ مِنَ الشَّرِّ كُلِّهِ، عَاجِلِهِ وَآجِلِهِ، مَا عَلِمْنَا مِنْهُ وَمَا لَمْ نَعْلَمْ.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ مِنْهُ عَبْدُكَ وَرَسُولُكَ مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَعُوذُ بِكَ مِنْ شَرِّ مَا اسْتَعَاذَكَ مِنْهُ عَبْدُكَ وَرَسُولُكَ مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.\nاللَّهُمَّ آتِنَا فِي الدُّنْيَا حَسَنَةً، وَفِي الْآخِرَةِ حَسَنَةً، وَقِنَا عَذَابَ النَّارِ.\nاللَّهُمَّ فَرِّجْ هَمَّ الْمَهْمُومِينَ، وَنَفِّسْ كَرْبَ الْمَكْرُوبِينَ وَاقْضِ الدَّيْنَ عَنِ الْمَدِينِينَ وَاشْفِ مَرْضَانَا وَمَرْضَى الْمُسْلِمِينَ، وَارْحَمْ مَوْتَانَا وَمَوْتَى الْمُسْلِمِينَ.\nاللَّهُمَّ أَعِزَّ الْإِسْلَامَ وَالْمُسْلِمِينَ وَاحْمِ حَوْزَةَ الدِّينِ، اللَّهُمَّ أَعِزَّ الْإِسْلَامَ وَالْمُسْلِمِينَ وَاحْمِ حَوْزَةَ الدِّينِ وَاجْعَلْ هَذَا الْبَلَدَ آمِنًا مُطْمَئِنًّا رَخَاءً، وَسَائِرَ بِلَادِ الْمُسْلِمِينَ.\nاللَّهُمَّ احْفَظْ عَلَى هَذِهِ الْبِلَادِ عَقِيدَتَهَا وَأَمْنَهَا وَرَخَاءَهَا وَاسْتِقْرَارِهَا وَعُلَمَاءَهَا وَوُلَاةَ أَمْرِهَا.\nاللَّهُمَّ وَفِّقْ وَلِيَّ أَمْرِنَا خَادِمَ الْحَرَمَيْنِ الشَّرِيفَيْنِ بِتَوْفِيقِكَ وَأَيِّدْهُ بِتَأْيِيدِكَ، وَانْصُرْ بِهِ دِينَكَ وَوَفِّقْهُ وَوَلِيَّ عَهْدِهِ، وَأَعْوَانَهُمْ لِكُلِّ مَا تُحِبُّ وَتَرْضَى وَلِكُلِّ مَا فِيهِ صَلَاحٌ لِلْبِلَادِ وَالْعِبَادِ وَلِكُلِّ مَا فِيهِ عِزٌّ وَنَصْرٌ وَتَمْكِينٌ لِلْإِسْلَامِ وَالْمُسْلِمِينَ.\nاللَّهُمَّ احْفَظْ جُنُودَنَا عَلَى ثُغُورِنَا بِعَيْنِكَ الَّتِي لَا تَنَامُ وَبِرُكْنِكَ الَّذِي لَا يُضَامُ، وَأَعِدْهُمْ إِلَى أَهْلِيهِمْ سَالِمِينَ غَانِمِينَ، بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِينَ.\nاللَّهُمَّ تَقَبَّلْ مِنَّا؛ إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ، وَاغْفِرْ لَنَا إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ، وَتُبْ عَلَيْنَا، إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ.\nاللَّهُمَّ إِنَّا نَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ وَمُعَافَاتِكَ مِنْ عُقُوبَتِكَ وَبِكَ مِنْكَ لَا نُحْصِي ثَنَاءً عَلَيْكَ.\nأَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ وَصَلِّ اللَّهُمَّ وَسَلِّمْ وَبَارِكْ عَلَى نَبِيِّنَا مُحَمَّدٍ وَعَلَى آلِهِ وَصَحْبِهِ أَجْمَعِينَ.",
