        "text": "اللَّهُمَّ اهْدِنَا فِيمَنْ هَدَيْتَ، وَعَافِنَا فِيمَنْ عَافَيْتَ، وَتَوَلَّنَا فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لَنَا فِيمَا أَعْطَيْتَ، وَقِنَا بِعِزَّتِكَ شَرَّ مَا قَضَيْتَ؛ فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ. تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ. لَكَ الْحَمْدُ عَلَى مَا قَضَيْتَ، وَلَكَ الشُّكْرُ عَلَى مَا أَعْطَيْتَ. نَسْتَغْفِرُكَ اللَّهُمَّ مِنْ جَمِيعِ الذُّنُوبِ وَالْخَطَايَا، وَنَتُوبُ إِلَيْكَ، نَسْتَغْفِرُكَ اللَّهُمَّ مِنْ جَمِيعِ الذُّنُوبِ وَالْخَطَايَا، وَنَتُوبُ إِلَيْكَ.\nاللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا، اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا، اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا. فَاعْفُ عَنَّا يَا كَرِيمُ، وَاعْفُ عَنَّا يَا رَحِيمُ، وَاعْفُ عَنَّا يَا أَكْرَمَ الْأَكْرَمِينَ.\nاللَّهُمَّ اغْفِرْ لَنَا مَا قَدَّمْنَا وَمَا أَخَّرْنَا، وَمَا أَسْرَرْنَا وَمَا أَعْلَنَّا، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنَّا؛ إِنَّكَ أَنْتَ السَّمِيعُ الْقَرِيبُ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ اجْعَلِ الْقُرْآنَ الْعَظِيمَ رَبِيعَ قُلُوبِنَا، وَنُورَ صُدُورِنَا، وَجَلَاءَ أَحْزَانِنَا، وَذَهَابَ هُمُومِنَا وَغُمُومِنَا، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ تَقَبَّلْ صِيَامَنَا، وَتَقَبَّلْ دُعَاءَنَا وَسُجُودَنَا وَرُكُوعَنَا، وَاغْفِرْ خَطِيئَاتِنَا، وَنَسْأَلُكَ الْعُلَا مِنَ الْجَنَّةِ. اللَّهُمَّ أَدْخِلْنَا الْجَنَّةَ مَعَ الْأَبْرَارِ، وَنَعُوذُ بِكَ مِنَ النَّارِ وَمِنْ خِزْيِ النَّارِ. اللَّهُمَّ أَجِرْنَا مِنَ النَّارِ، وَأَجِرْنَا مِنْ خِزْيِ النَّارِ، بِرَحْمَتِكَ يَا رَبَّنَا، يَا غَفُورُ يَا رَحِيمُ.\nاللَّهُمَّ اشْفِ مَرْضَانَا، وَارْحَمْ مَوْتَانَا، وَفُكَّ أَسْرَانَا. وَنَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ عِيشَةً نَقِيَّةً، وَمِيتَةً سَوِيَّةً، وَمَرَدًّا غَيْرَ مُخْزٍ وَلَا فَاضِحٍ.\nاللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ يَوْمِ السُّوءِ، وَمِنْ لَيْلَةِ السُّوءِ، وَمِنْ سَاعَةِ السُّوءِ، وَمِنْ صَاحِبِ السُّوءِ، وَمِنْ جَارِ السُّوءِ فِي دَارِ الْمُقَامَةِ.\nاللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ حُبِّ السُّمْعَةِ وَالرِّيَاءِ. اللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَنَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَنَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَنَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ إِنَّا عَبِيدُكَ، أَبْنَاءُ عَبِيدِكَ، وَأَبْنَاءُ إِمَائِكَ، نَوَاصِينَا بِيَدِكَ، مَاضٍ فِينَا حُكْمُكَ، عَدْلٌ فِينَا قَضَاؤُكَ. نَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ، سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ الْقُرْآنَ الْعَظِيمَ رَبِيعَ قُلُوبِنَا، وَنُورَ صُدُورِنَا، وَجَلَاءَ أَحْزَانِنَا، وَذَهَابَ هُمُومِنَا وَغُمُومِنَا، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ اغْفِرْ لِجَمِيعِ مَوْتَى الْمُسْلِمِينَ، الَّذِينَ شَهِدُوا لَكَ بِالْوَحْدَانِيَّةِ، وَلِنَبِيِّكَ بِالرِّسَالَةِ، وَمَاتُوا عَلَى ذَلِكَ. اللَّهُمَّ اغْفِرْ لَهُمْ وَارْحَمْهُمْ، وَعَافِهِمْ وَاعْفُ عَنْهُمْ، وَأَكْرِمْ نُزُلَهُمْ، وَوَسِّعْ مُدْخَلَهُمْ، وَاغْسِلْهُمْ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِمْ مِنَ الذُّنُوبِ وَالْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nوَصَلَّى اللَّهُ عَلَى نَبِيِّنَا مُحَمَّدٍ، وَعَلَى آلِهِ وَأَصْحَابِهِ أَجْمَعِينَ.",
        "note": "الشيخ قادر الكردي",
