        "itemNumber": 348,
        "text": "اللَّهُمَّ اهْدِنَا فِيمَنْ هَدَيْتَ، وَعَافِنَا فِيمَنْ عَافَيْتَ، وَتَوَلَّنَا فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لَنَا فِيمَا أَعْطَيْتَ، وَقِنَا بِعِزَّتِكَ شَرَّ مَا قَضَيْتَ؛ فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ.\nتَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ.\nلَكَ الْحَمْدُ عَلَى مَا قَضَيْتَ، وَلَكَ الشُّكْرُ عَلَى مَا أَعْطَيْتَ.\nنَسْتَغْفِرُكَ اللَّهُمَّ مِنْ جَمِيعِ الذُّنُوبِ وَالْخَطَايَا، وَنَتُوبُ إِلَيْكَ.\nاللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا.\nاللَّهُمَّ اغْفِرْ لَنَا مَا قَدَّمْنَا وَمَا أَخَّرْنَا، وَمَا أَسْرَرْنَا وَمَا أَعْلَنَّا، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنَّا؛ إِنَّكَ أَنْتَ السَّمِيعُ الْقَرِيبُ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ، الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ حَمْدًا يُوَافِي نِعَمَهُ وَيُكَافِئُ مَزِيدَهُ.\nاللَّهُمَّ لَكَ الْحَمْدُ بِالْإِسْلَامِ، وَلَكَ الْحَمْدُ بِالْإِيمَانِ، وَلَكَ الْحَمْدُ بِالْقُرْآنِ، وَلَكَ الْحَمْدُ أَنْ بَلَّغْتَنَا رَمَضَانَ.\nاللَّهُمَّ أَصْلِحْ قُلُوبَنَا وَأَزِلْ عُيُوبَنَا وَتَوَلَّنَا بِالْحُسْنَى وَزَيِّنَّا بِالتَّقْوَى، وَاجْمَعْ لَنَا خَيْرَ الْآخِرَةِ وَالْأُولَى وَارْزُقْنَا طَاعَتَكَ يَا رَبَّنَا.\nاللَّهُمَّ يَسِّرْنَا لِلْيُسْرَى وَجَنِّبْنَا الْعُسْرَى وَأَعِذْنَا مِنْ شُرُورِ أَنْفُسِنَا وَسَيِّئَاتِ أَعْمَالِنَا بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ، وَأَعِذْنَا مِنْ عَذَابِ النَّارِ وَعَذَابِ الْقَبْرِ وَفِتْنَةِ الْمَحْيَا وَالْمَمَاتِ وَفِتْنَةِ الْمَسِيحِ الدَّجَّالِ.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدِّينِ وَالدُّنْيَا وَالْآخِرَةِ، وَاجْمَعْ بَيْنَنَا وَبَيْنَ أَحْبَابِنَا فِي دَارِ كَرَامَتِكَ بِفَضْلِكَ وَرَحْمَتِكَ، وَاجْمَعْ بَيْنَنَا وَبَيْنَ أَحْبَابِنَا فِي دَارِ كَرَامَتِكَ بِفَضْلِكَ وَرَحْمَتِكَ بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ، بِرَحْمَتِكَ يَا أَكْرَمَ الْأَكْرَمِينَ.\nاللَّهُمَّ إِنَّا عَبِيدُكَ بَنُو عَبِيدُكَ بَنُو إِمَائِكَ، نَوَاصِينَا بِيَدِكَ، مَاضٍ فِينَا حُكْمُكَ، عَدْلٌ فِينَا قَضَاؤُكَ.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ، سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ الْقُرْآنَ الْعَظِيمَ رَبِيعَ قُلُوبِنَا، وَنُورَ صُدُورِنَا، وَجَلَاءَ أَحْزَانِنَا، وَذَهَابَ هُمُومِنَا وَغُمُومِنَا.\nاللَّهُمَّ ذَكِّرْنَا مِنْهُ مَا نَسِينَا، وَعَلِّمْنَا مِنْهُ مَا جَهِلْنَا، وَارْزُقْنَا تِلَاوَتَهُ آنَاءَ اللَّيْلِ وَأَطْرَافَ النَّهَارِ، وَاجْعَلْهُ لَنَا حُجَّةً، يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ اشْفِنَا بِشِفَائِكَ، اللَّهُمَّ اشْفِنَا بِشِفَائِكَ، وَدَاوِنَا بِدَوَائِكَ، وَأَغْنِنَا بِفَضْلِكَ عَمَّنْ سِوَاكَ.\nلَا إِلَهَ إِلَّا اللَّهُ الْمَلِكُ الْحَقُّ الْمُبِينُ مُحَمَّدٍ رَسُولُ اللَّهِ، الصَّادِقُ الْوَعْدِ الْأَمِينُ.\nاللَّهُمَّ ارْزُقْنَا شَفَاعَتَهُ، وَأَوْرِدْنَا حَوْضَهُ، وَاسْقِنَا مِنْ يَدِهِ الشَّرِيفَةِ شَرْبَةً هَنِيئَةً مَرِيئَةً لَا نَظْمَأُ بَعْدَهَا أَبَدًا.\nاللَّهُمَّ كَمَا آمَنَّا بِهِ وَلَمْ نَرَهُ، فَلَا تُفَرِّقْ بَيْنَنَا وَبَيْنَهُ حَتَّى تُدْخِلَنَا مُدْخَلَهُ، اللَّهُمَّ كَمَا آمَنَّا بِهِ وَلَمْ نَرَهُ، فَلَا تُفَرِّقْ بَيْنَنَا وَبَيْنَهُ حَتَّى تُدْخِلَنَا مُدْخَلَهُ.\nاللَّهُمَّ اجْزِهِ عَنَّا خَيْرَ مَا جَزَيْتَ بِهِ نَبِيًّا عَنْ قَوْمِهِ، وَرَسُولًا عَنْ أُمَّتِهِ، بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِينَ، مَا لَنَا سِوَاكَ نَرْجُوهُ مَا لَنَا سِوَاكَ نَدْعُوهُ، فَاسْتَجِبْ لَنَا دُعَاءَنَا كَمَا وَعَدْتَنَا.\nاللَّهُمَّ اجْعَلْنَا مِنْ عُتَقَائِكَ مِنَ النَّارِ، بِرَحْمَتِكَ يَا عَزِيزُ يَا غَفَّارُ.\nإِلَهَنَا وَخَالِقَنَا وَرَازِقَنَا، اجْتَمَعْنَا فِي مَسْجِدِنَا هَذَا، وَمِنَّا الشَّبَابُ، وَمِنَّا الْأَطْفَالُ، وَمِنَّا الشُّيُوخُ، وَمِنَّا النِّسَاءُ.\nدَعَوْنَاكَ دُعَاءً وَاحِدًا وَسُؤَالًا وَاحِدًا وَرَجَاءً وَاحِدًا.\nاللَّهُمَّ اجْعَلْنَا مِنْ عُتَقَائِكَ مِنَ النَّارِ، بِرَحْمَتِكَ يَا عَزِيزُ يَا غَفَّارُ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ.\nاللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ.",
