        "itemNumber": 349,
        "text": "اللَّهُمَّ اهْدِنَا فِيمَنْ هَدَيْتَ، وَعَافِنَا فِيمَنْ عَافَيْتَ، وَتَوَلَّنَا فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لَنَا فِيمَا أَعْطَيْتَ، وَقِنَا بِعِزَّتِكَ شَرَّ مَا قَضَيْتَ؛ فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ.\nتَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ.\nلَكَ الْحَمْدُ عَلَى مَا قَضَيْتَ، وَلَكَ الشُّكْرُ عَلَى مَا أَعْطَيْتَ.\nنَسْتَغْفِرُكَ اللَّهُمَّ مِنْ جَمِيعِ الذُّنُوبِ وَالْخَطَايَا، وَنَتُوبُ إِلَيْكَ.\nاللَّهُمَّ أَنْتَ رَبُّنَا لَا إِلَهَ إِلَّا أَنْتَ خَلَقْتَنَا وَنَحْنُ عَبِيدُكَ وَنَحْنُ عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْنَا نَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْنَا وَنَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيْنَا وَنَبُوءُ بِذُنُوبِنَا فَاغْفِرْ لَنَا فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ نَسْتَغْفِرُكَ وَنَتُوبُ إِلَيْكَ، نَسْتَغْفِرُكَ وَنَتُوبُ إِلَيْكَ تَوْبَةَ عَبْدٍ ظَالِمٍ لِنَفْسِهِ، لَا يَمْلِكُ لِنَفْسِهِ ضَرًّا وَلَا نَفْعًا، وَلَا مَوْتًا وَلَا حَيَاةً وَلَا نُشُورًا تُبْنَا إِلَيْكَ يَا اللَّهُ، وَنَدِمْنَا عَلَى مَا فَعَلْنَا وَعَزَمْنَا عَزْمًا أَكِيدًا عَلَى أَنَّنَا لَا نَعْصِيكَ أَبَدًا وَبَرِّئْنَا مِنْ كُلِّ دِينٍ يُخَالِفُ دِينَ الْإِسْلَامِ وَنَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ وَأَنْ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ.\nاللَّهُمَّ يَا مُجِيبَ السَّائِلِينَ يَا خَيْرَ الْمَسْؤُولِينَ يَا مُجِيبَ دَعْوَةِ الْمُضْطَرِّينَ، يَا مُجِيبَ دَعْوَةِ الْمُضْطَرِّينَ نَسْأَلُكَ يَا رَبَّنَا، التَّوْبَةَ الْكَامِلَةَ وَالْمَغْفِرَةَ الشَّامِلَةَ وَالْأَرْزَاقَ الْوَاسِعَةَ وَالْمَحَبَّةَ الْجَامِعَةَ وَالشَّفَاعَةَ الْقَائِمَةَ وَالدَّعْوَةَ الْمُسْتَجَابَةَ وَالْخُلَّةَ الصَّافِيَةَ وَفُكَّ وِثَاقِنَا مِنَ الْمَعْصِيَةِ نَسْأَلُكَ التَّوْبَةَ وَدَوَامَهَا وَنَعُوذُ بِكَ مِنَ الْمَعْصِيَةِ وَأَسْبَابِهَا نَسْأَلُكَ يَا رَبَّنَا، أَنْ تَجْعَلَ آخِرَ كَلَامِنَا مِنَ الدُّنْيَا لَا إِلَهَ إِلَّا اللَّهُ، لَا إِلَهَ إِلَّا اللَّهُ مُوقِنِينَ بِهَا وَلُطْفًا بِنَا يَا رَبَّنَا، لُطْفِ الْحَبِيبِ فِي الشِّدَّةِ وَنُزُولِهَا وَنَسْأَلُكَ يَا رَبَّنَا، مَا لَا عَيْنٌ رَأَتْ وَلَا أُذُنٌ سَمِعَتْ وَلَا خَطَرَ عَلَى قَلْبِ بَشَرٍ يَا مَنْ، يُجِيرُ وَلَا يُجَارُ عَلَيْهِ أَجِرْنَا مِنَ النَّارِ وَمِنْ خِزْيِ النَّارِ، أَجِرْنَا مِنَ النَّارِ وَمِنْ خِزْيِ النَّارِ وَمِنْ كُلِّ عَمَلٍ يُقَرِّبُنَا إِلَى النَّارِ، وَأَدْخِلْنَا الْجَنَّةَ مَعَ الْأَبْرَارِ، بِرَحْمَتِكَ يَا عَزِيزُ يَا غَفَّارُ.\nاللَّهُمَّ ارْفَعْ عَنَّا مِنَ الْبَلَاءِ مَا نَعْلَمُ وَمَا لَا نَعْلَمُ وَمَا أَنْتَ بِهِ أَعْلَمُ إِنَّكَ أَنْتَ اللَّهُ الْأَعَزُّ الْأَكْرَمُ يَا صَاحِبَ كُلِّ نَجْوَى يَا مُنْتَهَى كُلِّ شَكْوَى نَشْكُو إِلَيْكَ يَا رَبَّنَا، ضَعْفَنَا وَقِلَّةَ حِيلَتِنَا وَهَوَانَنَا عَلَى النَّاسِ يَا رَبَّ الْمُسْتَضْعَفِينَ يَا رَاحِمَ الضُّعَفَاءِ وَالْمَسَاكِينِ إِلَى مَنْ تَكِلُنَا إِلَى أَنْفُسِنَا لِنَهْلِكَ أَمْ إِلَى النَّاسِ فَنَكُونَ مِنَ الْمُعْدَمِينَ إِنْ كَانَتْ رَحْمَتُكَ وَقْفًا عَلَى الْمُحْسِنِينَ، فَمَنْ يَكُونُ لِلْمُسِيئِينَ إِلَّا أَنْتَ يَا رَبَّ الْعَالَمِينَ، وَإِنْ كُنْتَ لَا تَتَقَبَّلُ إِلَّا مِنْ عِبَادِكَ الْمُتَّقِينَ، فَمَنْ يَكُونُ لِلتَّائِبِينَ، فَمَنْ يَكُونُ لِلتَّائِبِينَ إِلَّا أَنْتَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ تُبْ عَلَيْنَا لِنَتُوبَ لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنَّا كُنَّا مِنَ الظَّالِمِينَ.\nرَبَّنَا اغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِي أَمْرِنَا، وَثَبِّتْ أَقْدَامَنَا وَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ.\nاللَّهُمَّ أَلِّفْ بَيْنَ قُلُوبِنَا، وَاخْتِمْ بِالْبَاقِيَاتِ الصَّالِحَاتِ أَعْمَالَنَا وَاجْعَلِ بِلَادَنَا آمِنَةً مُطْمَئِنَّةً سَخَاءً رَخَاءً، وَسَائِرَ بِلَادِ الْمُسْلِمِينَ.\nاللَّهُمَّ انْصُرِ الْإِسْلَامَ وَأَعِزَّ الْمُسْلِمِينَ وَأَذِلَّ الشِّرْكَ وَالْمُشْرِكِينَ، وَدَمِّرْ أَعْدَاءَ الدِّينِ، وَانْصُرْ عِبَادَكَ الْمُوَحِّدِينَ، وَانْصُرْ عِبَادَكَ الْمُوَحِّدِينَ فِي كُلِّ مَكَانٍ.\nاللَّهُمَّ أَغْنِنَا بِحَلَالِكَ عَنْ حَرَامِكَ وَبِطَاعَتِكَ عَنْ مَعْصِيَتِكَ وَبِفَضْلِكَ وَجُودِكَ وَكَرَمِكَ عَمَّنْ سِوَاكَ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ.\nاللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ.",
        "note": "الشيخ قادر الكردي",
