        "itemNumber": 350,
        "text": "اللَّهُمَّ اهْدِنَا فِيمَنْ هَدَيْتَ، وَعَافِنَا فِيمَنْ عَافَيْتَ، وَتَوَلَّنَا فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لَنَا فِيمَا أَعْطَيْتَ، وَقِنَا بِعِزَّتِكَ شَرَّ مَا قَضَيْتَ؛ فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ. تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ. لَكَ الْحَمْدُ عَلَى مَا قَضَيْتَ، وَلَكَ الشُّكْرُ عَلَى مَا أَعْطَيْتَ. نَسْتَغْفِرُكَ اللَّهُمَّ مِنْ جَمِيعِ الذُّنُوبِ وَالْخَطَايَا، وَنَتُوبُ إِلَيْكَ.\nاللَّهُمَّ لَكَ أَسْلَمْنَا، وَبِكَ آمَنَّا، وَعَلَيْكَ تَوَكَّلْنَا، وَإِلَيْكَ أَنَبْنَا، وَبِكَ خَاصَمْنَا؛ فَاغْفِرْ لَنَا مَا قَدَّمْنَا وَمَا أَخَّرْنَا، وَمَا أَسْرَرْنَا وَمَا أَعْلَنَّا، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنَّا. إِنَّكَ أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ، لَا إِلَهَ إِلَّا أَنْتَ.\nاللَّهُمَّ مَتِّعْنَا بِالنَّظَرِ إِلَى وَجْهِكَ الْكَرِيمِ. اللَّهُمَّ اجْعَلْنَا مِنَ الَّذِينَ تَجْرِي مِنْ تَحْتِهِمُ الْأَنْهَارُ فِي جَنَّاتِ النَّعِيمِ؛ دَعْوَاهُمْ فِيهَا سُبْحَانَكَ اللَّهُمَّ، وَتَحِيَّتُهُمْ فِيهَا سَلَامٌ، وَآخِرُ دَعْوَاهُمْ أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ.\nاللَّهُمَّ ثَبِّتْنَا بِالْقَوْلِ الثَّابِتِ فِي الْحَيَاةِ الدُّنْيَا وَفِي الْآخِرَةِ، اللَّهُمَّ ثَبِّتْنَا بِالْقَوْلِ الثَّابِتِ فِي الْحَيَاةِ الدُّنْيَا وَفِي الْآخِرَةِ. اللَّهُمَّ ثَقِّلْ مَوَازِينَنَا، وَارْفَعْ دَرَجَاتِنَا، وَاغْفِرْ خَطِيئَاتِنَا، وَحَقِّقْ إِيمَانَنَا، وَتَقَبَّلْ صَلَاتَنَا وَصِيَامَنَا وَقِيَامَنَا وَرُكُوعَنَا وَسُجُودَنَا وَدُعَاءَنَا، وَنَسْأَلُكَ الْعُلَا مِنَ الْجَنَّةِ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ اجْعَلِ الْقُرْآنَ الْعَظِيمَ لَنَا فِي الدُّنْيَا قَرِينًا، وَفِي الْقَبْرِ مُؤْنِسًا، وَعَلَى الصِّرَاطِ نُورًا، وَفِي الْقِيَامَةِ شَفِيعًا، وَفِي الْجَنَّةِ رَفِيقًا، وَمِنَ النَّارِ سِتْرًا وَحِجَابًا، وَإِلَى الْخَيْرَاتِ كُلِّهَا دَلِيلًا وَإِمَامًا، بِفَضْلِكَ وَكَرَمِكَ يَا أَكْرَمَ الْأَكْرَمِينَ. اللَّهُمَّ اجْعَلْهُ حُجَّةً لَنَا لَا عَلَيْنَا، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ يَا صَاحِبَ كُلِّ نَجْوَى، وَيَا مُنْتَهَى كُلِّ شَكْوَى، يَا رَبَّ الْمُسْلِمِينَ، نَشْكُو إِلَيْكَ حَالَ الْمُسْلِمِينَ فِي كُلِّ مَكَانٍ، وَنَشْكُو إِلَيْكَ بَثَّنَا وَحُزْنَنَا وَمَا أَهَمَّنَا؛ فَلَا تَكِلْنَا يَا رَبَّنَا إِلَى مَنْ لَا يَخَافُكَ وَلَا يَرْحَمُنَا بِذُنُوبِنَا، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ أَجِبْ دَعْوَتَنَا، وَاقْبَلْ تَوْبَتَنَا، وَسَدِّدْ أَلْسِنَتَنَا، وَارْحَمْ فِي الدُّنْيَا غُرْبَتَنَا، وَفِي الْقُبُورِ وَحْشَتَنَا، وَثَبِّتْ تَحْتَ التُّرَابِ حُجَّتَنَا؛ فَأَنْتَ قُلْتَ وَقَوْلُكَ الْحَقُّ: «يُثَبِّتُ اللَّهُ الَّذِينَ آمَنُوا بِالْقَوْلِ الثَّابِتِ فِي الْحَيَاةِ الدُّنْيَا وَفِي الْآخِرَةِ». وَارْحَمْ مَوْقِفَنَا غَدًا عُرَاةً بَيْنَ يَدَيْكَ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ يَا صَاحِبَ كُلِّ نَجْوَى، وَيَا مُنْتَهَى كُلِّ شَكْوَى، إِنَّا ضُعَفَاءُ فَقَوِّنَا، أَذِلَّاءُ فَأَعِزَّنَا، مَغْلُوبُونَ فَانْصُرْنَا، مُذْنِبُونَ فَاغْفِرْ لَنَا، مُقَصِّرُونَ فَاعْفُ عَنَّا، مُتَفَرِّقُونَ فَاجْمَعْنَا، مُخْتَلِفُونَ فَوَحِّدْنَا، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ أَعْطِنَا وَلَا تَحْرِمْنَا، وَأَكْرِمْنَا وَلَا تُهِنَّا، وَأَعِنَّا وَلَا تُعِنْ عَلَيْنَا، وَانْصُرْنَا وَلَا تَنْصُرْ عَلَيْنَا، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ اشْفِنَا بِشِفَائِكَ، وَدَاوِنَا بِدَوَائِكَ، وَأَغْنِنَا بِفَضْلِكَ عَمَّنْ سِوَاكَ. لَا إِلَهَ إِلَّا اللَّهُ، لَا إِلَهَ إِلَّا اللَّهُ، مُحَمَّدٌ رَسُولُ اللَّهِ.\nاللَّهُمَّ ارْزُقْنَا شَفَاعَتَهُ، وَأَوْرِدْنَا حَوْضَهُ، وَأَوْرِدْنَا حَوْضَهُ، وَاسْقِنَا مِنْ يَدِهِ الشَّرِيفَةِ شَرْبَةً هَنِيئَةً لَا نَظْمَأُ بَعْدَهَا أَبَدًا. اللَّهُمَّ كَمَا آمَنَّا بِهِ وَلَمْ نَرَهُ، فَلَا تُفَرِّقْ بَيْنَنَا وَبَيْنَهُ حَتَّى تُدْخِلَنَا مُدْخَلَهُ. اللَّهُمَّ اجْزِهِ عَنَّا خَيْرَ مَا جَزَيْتَ نَبِيًّا عَنْ قَوْمِهِ، وَرَسُولًا عَنْ أُمَّتِهِ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nمَا لَنَا سِوَاكَ نَرْجُوهُ، وَمَا لَنَا سِوَاكَ نَدْعُوهُ؛ فَاسْتَجِبْ لَنَا دُعَاءَنَا كَمَا وَعَدْتَنَا.\nاللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا، اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا، إِلَهَنَا، يَا أَكْرَمَ الْأَكْرَمِينَ.\nوَصَلَّى اللَّهُ عَلَى نَبِيِّنَا مُحَمَّدٍ، وَعَلَى آلِهِ وَأَصْحَابِهِ أَجْمَعِينَ.",
