        "itemNumber": 354,
        "text": "اللَّهُمَّ اهْدِنَا فِيمَنْ هَدَيْتَ، وَعَافِنَا فِيمَنْ عَافَيْتَ، وَتَوَلَّنَا فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لَنَا فِيمَا أَعْطَيْتَ تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ.\nلَكَ الْحَمْدُ عَلَى مَا قَضَيْتَ، وَلَكَ الشُّكْرُ عَلَى مَا آتَيْتَ. نَسْتَغْفِرُكَ اللَّهُمَّ مِنْ كُلِّ ذَنْبٍ وَخَطِيئَةٍ، وَنَتُوبُ إِلَيْكَ، وَنُؤْمِنُ بِكَ، وَنَتَوَكَّلُ عَلَيْكَ.\nأَنْتَ الْغَنِيُّ وَنَحْنُ الْفُقَرَاءُ أَنْتَ الْقَوِيُّ وَنَحْنُ الضُّعَفَاءُ إِلَيْكَ.\nاللَّهُمَّ يَا وَاصِلَ الْمُنْقَطِعِينَ، أَوْصِلْنَا إِلَيْكَ.\nاللَّهُمَّ هَبْ لَنَا مِنْكَ عَمَلًا صَالِحًا يُقَرِّبُنَا إِلَيْكَ.\nاللَّهُمَّ اسْتُرْنَا فَوْقَ الْأَرْضِ، وَتَحْتَ الْأَرْضِ، وَيَوْمَ الْعَرْضِ عَلَيْكَ بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ رُدَّ الْمُسْلِمِينَ إِلَى دِينِكَ رَدًّا جَمِيلًا، اللَّهُمَّ رُدَّ الْمُسْلِمِينَ إِلَى دِينِكَ رَدًّا جَمِيلًا، رُدَّ الْمُسْلِمِينَ إِلَى دِينِكَ رَدًّا جَمِيلًا اللَّهُمَّ انْصُرْنَا عَلَى أَنْفُسِنَا.\nاللَّهُمَّ اسْتَجِبْ دُعَاءَنَا اللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنَ الْمَوْتِ وَكَرْبَتِهِ، وَالْقَبْرِ وَغُمَّتِهِ، وَالصِّرَاطِ وَزَلَّتِهِ، وَيَوْمِ الْقِيَامَةِ وَرَوْعَتِهِ بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ اجْعَلْنَا نَخْشَاكَ كَأَنَّنَا نَرَاكَ، وَأَسْعِدْنَا بِتَقْوَاكَ، وَمَتِّعْنَا بِرُؤْيَاكَ، وَاجْمَعْنَا مَعَ نَبِيِّكَ وَمُصْطَفَاكَ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ انْصُرِ الْإِسْلَامَ وَأَعِزَّ الْمُسْلِمِينَ، اللَّهُمَّ انْصُرِ الْإِسْلَامَ وَأَعِزَّ الْمُسْلِمِينَ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ اهْدِنَا وَوَفِّقْنَا إِلَى الْحَقِّ وَإِلَى الصِّرَاطِ الْمُسْتَقِيمِ بِبَرَكَةِ الْقُرْآنِ وَاعْفُ عَنَّا يَا كَرِيمُ، وَعَافِنَا يَا رَحِيمُ.\nاللَّهُمَّ اجْعَلِ الْقُرْآنَ رَبِيعَ قُلُوبِنَا، وَنُورَ صُدُورِنَا اللَّهُمَّ اجْعَلِ الْقُرْآنَ حُجَّةً لَنَا وَلَا تَجْعَلْهُ حُجَّةً عَلَيْنَا.\nاللَّهُمَّ اجْعَلْنَا مِمَّنْ يَقْرَأُهُ فَيَرْقَى، اللَّهُمَّ اجْعَلْنَا مِمَّنْ يَقْرَأُهُ فَيَرْقَى وَلَا تَجْعَلْنَا مِمَّنْ يَقْرَأُهُ فَيَزِلَّ وَيَشْقَى بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ ارْزُقْنَا الْقَنَاعَةَ، اللَّهُمَّ ارْزُقْنَا الْقَنَاعَةَ، ارْزُقْنَا الْقَنَاعَةَ اللَّهُمَّ حَبِّبْنَا فِي صَلَاةِ الْجَمَاعَةِ.\nاللَّهُمَّ ذَكِّرْنَا بِالْمَوْتِ كُلَّ سَاعَةٍ.\nاللَّهُمَّ احْشُرْنَا مَعَ النَّبِيِّ الْمُصْطَفَى صَاحِبَ الشَّفَاعَةِ بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ زَيِّنَّا بِزِينَةِ الْقُرْآنِ.\nاللَّهُمَّ أَدْخِلْنَا الْجَنَّةَ بِشَفَاعَةِ الْقُرْآنِ.\nاللَّهُمَّ أَكْرِمْنَا بِكَرَامَةِ الْقُرْآنِ.\nاللَّهُمَّ أَلْبِسْنَا بِخِلْعَةِ الْقُرْآنِ.\nاللَّهُمَّ شَرِّفْنَا بِشَرَفِ الْقُرْآنِ بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ أَحْسِنْ وُقُوفَنَا بَيْنَ يَدَيْكَ، اللَّهُمَّ لَا تُخْزِنَا يَوْمَ الْعَرْضِ عَلَيْكَ.\nاللَّهُمَّ تَقَبَّلْ صَلَاتَنَا اللَّهُمَّ تَقَبَّلْ صِيَامَنَا.\nاللَّهُمَّ تَقَبَّلْ قِيَامَنَا وَرُكُوعَنَا وَسُجُودَنَا.\nاللَّهُمَّ اجْعَلْنَا مِنْ عُتَقَائِكَ مِنَ النَّارِ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ أَجِرْنَا مِنَ النَّارِ.\nاللَّهُمَّ أَجِرْنَا مِنْ خِزْيِ النَّارِ.\nاللَّهُمَّ أَجِرْنَا مِنْ كُلِّ عَمَلٍ يُقَرِّبُنَا إِلَى النَّارِ.\nاللَّهُمَّ أَدْخِلْنَا الْجَنَّةَ مَعَ الْأَبْرَارِ، بِرَحْمَتِكَ يَا عَزِيزُ يَا غَفَّارُ.\nاللَّهُمَّ اجْعَلْنَا يَا مَوْلَانَا فِي شَهْرِنَا هَذَا، وَفِي يَوْمِنَا هَذَا، وَفِي لَيْلَتِنَا هَذِهِ، مِنْ عُتَقَائِكَ مِنَ النَّارِ، وَاجْعَلْنَا مِنَ الْمَقْبُولِينَ الْفَائِزِينَ، وَاجْعَلْنَا مِنَ الْمَقْبُولِينَ الْفَائِزِينَ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ ارْحَمْنَا.\nيَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا، اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا، فَاعْفُ عَنَّا يَا كَرِيمُ، فَاعْفُ عَنَّا يَا أَرْحَمَ الرَّاحِمِينَ، وَصَلَّى اللَّهُ عَلَى نَبِيِّنَا مُحَمَّدٍ وَعَلَى آلِهِ وَأَصْحَابِهِ أَجْمَعِينَ.",
