        "itemNumber": 355,
        "text": "اللَّهُمَّ اهْدِنَا فِيمَنْ هَدَيْتَ، وَعَافِنَا فِيمَنْ عَافَيْتَ، وَتَوَلَّنَا فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لَنَا فِيمَا أَعْطَيْتَ، وَقِنَا بِرَحْمَتِكَ، وَاصْرِفْ عَنَّا شَرَّ مَا قَضَيْتَ، فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ.\nتَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ.\nاللَّهُمَّ آتِ نُفُوسَنَا تَقْوَاهَا، وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا، أَنْتَ وَلِيُّهَا وَمَوْلَاهَا.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ الْجَنَّةَ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ وَعَمَلٍ وَنَعُوذُ بِكَ مِنَ النَّارِ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ وَعَمَلٍ.\nاللَّهُمَّ أَحْسِنْ عَاقِبَتَنَا فِي الْأُمُورِ كُلِّهَا، وَأَجِرْنَا مِنْ خِزْيِ الدُّنْيَا وَعَذَابِ الْآخِرَةِ يَا حَيُّ يَا قَيُّومُ، بِرَحْمَتِكَ نَسْتَغِيثُ، أَصْلِحْ لَنَا شَأْنَنَا كُلَّهُ وَلَا تَكِلْنَا إِلَى أَنْفُسِنَا طَرْفَةَ عَيْنٍ يَا مَنْ، يُجِيرُ وَلَا يُجَارُ عَلَيْهِ يَا مَنْ لَا مَلْجَأَ مِنْهُ إِلَّا إِلَيْهِ.\nاللَّهُمَّ احْرُسْنَا بِعَيْنِكَ الَّتِي لَا تَنَامُ وَاكْنُفْنَا بِكَنَفِكَ الَّذِي لَا يُرَامُ وَاحْفَظْنَا بِعِزِّكَ الَّذِي لَا يُضَامُ.\nاللَّهُمَّ إِنَّا نَسْتَدْفِعُ بِكَ كُلَّ سُوءٍ، اللَّهُمَّ إِنَّا نَسْتَدْفِعُ بِكَ كُلَّ سُوءٍ وَنَعُوذُ بِكَ مِنْ شَرِّ قَضَاءِ السُّوءِ، وَمِنْ شَرِّ كُلِّ ذِي شَرٍّ أَنْ تَأْخُذَ بِنَاصِيَتِهِ.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ دَوَامَ عَافِيَةٍ مِنْ جَمِيعِ الْأَمْرَاضِ وَالْبَلَايَا.\nاللَّهُمَّ لَا تَدَعْ لَنَا ذَنْبًا إِلَّا غَفَرْتَهُ، وَلَا هَمًّا إِلَّا فَرَّجْتَهُ، وَلَا دَيْنًا إِلَّا قَضَيْتَهُ، وَلَا مُبْتَلًى إِلَّا عَافَيْتَهُ وَلَا مَرِيضًا إِلَّا شَفَيْتَهُ، وَلَا وَلَدًا إِلَّا أَصْلَحْتَهُ وَلَا تَائِبًا إِلَّا قَبِلْتَهُ وَلَا ضَالًّا إِلَّا هَدَيْتَهُ وَلَا عَمَلًا صَالِحًا إِلَّا قَبِلْتَهُ وَلَا مَيِّتًا إِلَّا رَحِمْتَهُ وَلَا حَاجَةً مِنْ حَوَائِجِ الدُّنْيَا وَالْآخِرَةِ هِيَ لَكَ رِضًا وَلَنَا فِيهَا صَلَاحٌ إِلَّا أَعَنْتَنَا عَلَى قَضَائِهَا.\nاللَّهُمَّ احْفَظْ بِلَادَنَا وَبِلَادَ الْمُسْلِمِينَ مِنْ كُلِّ سُوءٍ وَمَكْرُوهٍ وَاجْعَلِ هَذِهِ الْبِلَادَ شَامِخَةً عَزِيزَةً حَامِيَةً لِجَنَابِ التَّوْحِيدِ وَالسُّنَّةِ إِلَى يَوْمِ الدِّينِ.\nاللَّهُمَّ وَفِّقْ وَلِيَّ أَمْرِنَا وَإِمَامَنَا وَوَلِيَّ عَهْدِهِ لِكُلِّ مَا تُحِبُّ وَتَرْضَى، وَاجْزِهِمْ عَنَّا وَعَنِ الْبِلَادِ وَعَنِ الْإِسْلَامِ وَالْمُسْلِمِينَ خَيْرَ الْجَزَاءِ، بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِينَ.\nاللَّهُمَّ هَذَا الدُّعَاءُ وَمِنْكَ الْإِجَابَةُ، وَهَذَا الْجُهْدُ وَعَلَيْكَ التُّكْلَانُ وَصَلِّ اللَّهُمَّ وَسَلِّمْ وَبَارِكْ عَلَى نَبِيِّنَا مُحَمَّدٍ وَعَلَى آلِهِ وَصَحْبِهِ أَجْمَعِينَ.",
        "note": "الشيخ ياسر الدوسري",
