        "text": "اللَّهُمَّ اهْدِنَا فِيمَنْ هَدَيْتَ، وَعَافِنَا فِيمَنْ عَافَيْتَ، وَتَوَلَّنَا فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لَنَا فِيمَا أَعْطَيْتَ، وَقِنَا بِعِزَّتِكَ شَرَّ مَا قَضَيْتَ؛ فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ. تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ. لَكَ الْحَمْدُ عَلَى مَا قَضَيْتَ، وَلَكَ الشُّكْرُ عَلَى مَا أَعْطَيْتَ. نَسْتَغْفِرُكَ اللَّهُمَّ مِنْ جَمِيعِ الذُّنُوبِ وَالْخَطَايَا، وَنَتُوبُ إِلَيْكَ.\nاللَّهُمَّ اقْسِمْ لَنَا مِنْ خَشْيَتِكَ مَا تَحُولُ بِهِ بَيْنَنَا وَبَيْنَ مَعْصِيَتِكَ، وَمِنْ طَاعَتِكَ مَا تُبَلِّغُنَا بِهِ جَنَّتَكَ، وَمِنَ الْيَقِينِ مَا تُهَوِّنُ بِهِ عَلَيْنَا مَصَائِبَ الدُّنْيَا. وَمَتِّعْنَا اللَّهُمَّ بِأَسْمَاعِنَا وَأَبْصَارِنَا وَقُوَّاتِنَا أَبَدًا مَا أَبْقَيْتَنَا، وَاجْعَلْهُ الْوَارِثَ مِنَّا، وَاجْعَلْ ثَأْرَنَا عَلَى مَنْ ظَلَمَنَا، وَانْصُرْنَا عَلَى مَنْ عَادَانَا. وَلَا تَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّنَا، وَلَا مَبْلَغَ عِلْمِنَا، وَلَا إِلَى النَّارِ مَصِيرَنَا، وَلَا إِلَى النَّارِ مَصِيرَنَا. وَاجْعَلِ اللَّهُمَّ الْجَنَّةَ دَارَنَا وَقَرَارَنَا، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا. فَاعْفُ عَنَّا يَا كَرِيمُ، وَاعْفُ عَنَّا يَا رَحِيمُ، وَاعْفُ عَنَّا يَا أَكْرَمَ الْأَكْرَمِينَ.\nاللَّهُمَّ اغْفِرْ لَنَا مَا قَدَّمْنَا وَمَا أَخَّرْنَا، وَمَا أَسْرَرْنَا وَمَا أَعْلَنَّا، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنَّا؛ إِنَّكَ أَنْتَ السَّمِيعُ الْقَرِيبُ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ خَيْرَ الْمَسْأَلَةِ، وَخَيْرَ الدُّعَاءِ، وَخَيْرَ النَّجَاحِ، وَخَيْرَ الْعِلْمِ، وَخَيْرَ الْعَمَلِ، وَخَيْرَ الثَّوَابِ، وَخَيْرَ الْحَيَاةِ، وَخَيْرَ الْمَمَاتِ. وَثَبِّتْنَا، وَثَقِّلْ مَوَازِينَنَا، وَحَقِّقْ إِيمَانَنَا، وَارْفَعْ دَرَجَاتِنَا، وَتَقَبَّلْ صَلَاتَنَا وَصِيَامَنَا وَسُجُودَنَا وَرُكُوعَنَا، وَاغْفِرْ خَطِيئَاتِنَا، وَنَسْأَلُكَ الْعُلَا مِنَ الْجَنَّةِ.\nاللَّهُمَّ إِنَّا نَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ، وَعَزَائِمَ مَغْفِرَتِكَ، وَالسَّلَامَةَ مِنْ كُلِّ إِثْمٍ، وَالْغَنِيمَةَ مِنْ كُلِّ بِرٍّ، وَالْفَوْزَ بِالْجَنَّةِ، وَالنَّجَاةَ مِنَ النَّارِ. اللَّهُمَّ أَجِرْنَا مِنَ النَّارِ، وَأَجِرْنَا مِنْ خِزْيِ النَّارِ، وَأَدْخِلْنَا الْجَنَّةَ مَعَ الْأَبْرَارِ، بِرَحْمَتِكَ يَا عَزِيزُ يَا غَفَّارُ، بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِينَ.\nإِلَهَنَا وَخَالِقَنَا وَرَازِقَنَا، اجْتَمَعْنَا فِي مَسْجِدِنَا هَذَا، وَمِنَّا الشَّبَابُ، وَمِنَّا الْأَطْفَالُ، وَمِنَّا الشُّيُوخُ، وَمِنَّا النِّسَاءُ. دَعَوْنَاكَ دُعَاءً وَاحِدًا، وَرَجَوْنَاكَ رَجَاءً وَاحِدًا. اللَّهُمَّ اجْعَلْنَا مِنْ عُتَقَائِكَ مِنَ النَّارِ، اللَّهُمَّ اجْعَلْنَا مِنْ عُتَقَائِكَ مِنَ النَّارِ، وَاجْعَلْنَا مِنْ عُتَقَائِكَ فِي شَهْرِ رَمَضَانَ، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ اشْفِ مَرْضَانَا، وَارْحَمْ مَوْتَانَا، وَفُكَّ أَسْرَانَا، وَنَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى. اللَّهُمَّ لَا تَدَعْ لَنَا ذَنْبًا إِلَّا غَفَرْتَهُ، وَلَا هَمًّا إِلَّا فَرَّجْتَهُ، وَلَا دَيْنًا إِلَّا قَضَيْتَهُ، وَلَا حَاجَةً مِنْ حَوَائِجِ الدُّنْيَا وَالْآخِرَةِ إِلَّا قَضَيْتَهَا، بِرَحْمَتِكَ يَا رَبَّ الْعَالَمِينَ.\nاللَّهُمَّ اجْعَلِ الْقُرْآنَ الْعَظِيمَ رَبِيعَ قُلُوبِنَا، وَنُورَ صُدُورِنَا.\nرَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً، وَفِي الْآخِرَةِ حَسَنَةً، وَقِنَا عَذَابَ النَّارِ.\nاللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ. اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ.",
        "note": "الشيخ قادر الكردي",
